    "Scan de code met je bank-app: bedrag en kenmerk staan er al in. Liever handmatig? Neem dan bovenstaande gegevens over en vermeld het kenmerk.": "Scan the code with your banking app: the amount and reference are already filled in. Prefer to do it manually? Copy the details above and quote the reference.",
