    "Jouw bestanden zijn van jou. Dit logboek laat zien wat ermee is gebeurd.": "Your files are yours. This log shows what has happened with them.",
    "Dit logboek toont elke keer dat een bestand van dit project is bekeken, gedownload of gedeeld.": "This log shows every time a file of this project was viewed, downloaded or shared.",
