    "FACTUUR": "INVOICE",
    "Factuur betaald: {x}": "Invoice paid: {x}",
    "Er staat een factuur voor je klaar: {x}": "An invoice is ready for you: {x}",
    "Zending: {x}": "Shipment: {x}",
    "goedgekeurd": "approved",
    "Uitleg: {term}": "Explanation: {term}",
    "Lees meer op de site": "Read more on the site",
    "De statistische norm die bepaalt hoeveel afwijkingen een steekproef mag bevatten voordat de hele batch wordt afgekeurd. Elke inspectie in je portaal wordt tegen deze norm gemeten.": "The statistical norm that determines how many deviations a sample may contain before the whole batch is rejected. Every inspection in your portal is measured against this norm.",
    "Een contract dat is opgesteld om afdwingbaar te zijn bij Chinese rechtbanken, getekend vóór er één bestand de deur uit gaat. Een westerse NDA alleen is dat in de praktijk vaak niet.": "A contract drafted to be enforceable in Chinese courts, signed before a single file leaves the door. A western NDA alone often is not, in practice.",
    "De stap waarin je ontwerp wordt getoetst aan het productieproces dat het echt gaat maken, vóór er tooling wordt besteld. Een mooi CAD bestand en een maakbaar onderdeel zijn niet hetzelfde.": "The step in which your design is tested against the production process that will actually make it, before any tooling is ordered. A nice CAD file and a manufacturable part are not the same thing.",
    "De kleinste oplage die een fabriek wil draaien. Voor spuitgietwerk ligt die doorgaans hoger dan voor CNC of plaatwerk, omdat de mal moet worden terugverdiend.": "The smallest run a factory is willing to produce. For injection moulding it is usually higher than for CNC or sheet metal, because the mould has to earn itself back.",
    "De controle van binnenkomend materiaal vóórdat de productie start, zodat een afwijking in de grondstof nooit een hele run kan raken.": "The check of incoming material before production starts, so a deviation in the raw material can never affect a whole run.",
    "Controles tijdens de productierun zelf, niet pas aan het einde — zo wordt een afwijking gevonden terwijl die nog goedkoop te herstellen is.": "Checks during the production run itself, not only at the end — so a deviation is found while it is still cheap to fix.",
    "De eindcontrole op de afgeronde batch, vlak vóór verzending, gemeten tegen hetzelfde golden sample waarmee de run begon.": "The final check on the finished batch, just before shipment, measured against the same golden sample the run started with.",
    "Het allereerste schot uit een nieuwe mal. Een T0 is zelden meteen goed — deze ronde laat zien wat er aan de mal moet worden bijgesteld.": "The very first shot from a new mould. A T0 is rarely right straight away — this round shows what needs adjusting on the mould.",
    "De sampleronde na de eerste bijstelling van de mal. Elke volgende ronde brengt het sample dichter bij het exemplaar dat jij goedkeurt.": "The sample round after the first adjustment of the mould. Each following round brings the sample closer to the piece you approve.",
    "De ronde na de tweede bijstelling, vaak de laatste verfijning zoals polijstwerk aan de mal. Keur jij deze goed, dan wordt dit exemplaar meestal het golden sample.": "The round after the second adjustment, often the final refinement such as polishing the mould. If you approve it, this piece usually becomes the golden sample.",
    "Het sample dat jij goedkeurt als dé standaard. Elke inspectie tijdens de productie meet de batch tegen precies dit exemplaar — niet tegen een gevoel.": "The sample you approve as the standard. Every inspection during production measures the batch against exactly this piece — not against a feeling.",
    "Het officiële vervoersdocument van een zeevracht: het bewijs dat de lading aan boord is én het document waarmee de container op de bestemming wordt vrijgegeven.": "The official transport document of a sea freight shipment: proof that the cargo is on board and the document that releases the container at the destination.",
    /* factuurmodule fase 5 — de herinneringsteksten. De {plaatshouders}
       moeten blijven staan: i18nTpl/invTpl vult ze ná de vertaling in, en
       test/i18n-invoice.test.mjs faalt als er één verdwijnt. */
    "Herinnering: factuur {nummer} vervalt {vervaldatum}": "Reminder: invoice {nummer} is due {vervaldatum}",
    "Beste {naam},\n\nEen vriendelijke herinnering: factuur {nummer} van {bedrag} vervalt op {vervaldatum}.\n\nIs de betaling al onderweg, dan kun je dit bericht als niet verzonden beschouwen.\n\nMet vriendelijke groet,\n{afzender}": "Dear {naam},\n\nA friendly reminder: invoice {nummer} for {bedrag} is due on {vervaldatum}.\n\nIf your payment is already on its way, please disregard this message.\n\nKind regards,\n{afzender}",
    "Factuur {nummer} staat nog open": "Invoice {nummer} is still outstanding",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} is op {vervaldatum} vervallen en staat nog open. Waarschijnlijk is het je ontgaan.\n\nHet openstaande bedrag is {openstaand}. Klopt er iets niet, laat het dan weten — dan lossen we het samen op.\n\nMet vriendelijke groet,\n{afzender}": "Dear {naam},\n\nInvoice {nummer} for {bedrag} fell due on {vervaldatum} and is still outstanding. It has probably slipped your attention.\n\nThe outstanding amount is {openstaand}. If something is not right, let us know and we will sort it out together.\n\nKind regards,\n{afzender}",
    "Tweede herinnering: factuur {nummer}": "Second reminder: invoice {nummer}",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} staat sinds {vervaldatum} open. Het openstaande bedrag is {openstaand}.\n\nWe hebben nog geen betaling ontvangen en ook geen bericht. Wil je de betaling deze week in orde maken, of laten weten waar het aan ligt?\n\nMet vriendelijke groet,\n{afzender}": "Dear {naam},\n\nInvoice {nummer} for {bedrag} has been outstanding since {vervaldatum}. The outstanding amount is {openstaand}.\n\nWe have received neither payment nor a message. Could you arrange payment this week, or let us know what is holding it up?\n\nKind regards,\n{afzender}",
    "Laatste aanmaning: factuur {nummer}": "Final notice: invoice {nummer}",
    "Beste {naam},\n\nOndanks eerdere herinneringen staat factuur {nummer} nog open. Het openstaande bedrag is {openstaand}, vervallen op {vervaldatum}.\n\nDit is de laatste aanmaning. Zonder betaling of bericht binnen veertien dagen dragen we de vordering over.\n\nMet vriendelijke groet,\n{afzender}": "Dear {naam},\n\nDespite earlier reminders, invoice {nummer} is still outstanding. The outstanding amount is {openstaand}, due since {vervaldatum}.\n\nThis is the final notice. Without payment or a message within fourteen days we will hand the claim over.\n\nKind regards,\n{afzender}",
    "Over factuur {nummer}": "About invoice {nummer}",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} staat nog open; het openstaande bedrag is {openstaand}.\n\nMet vriendelijke groet,\n{afzender}": "Dear {naam},\n\nInvoice {nummer} for {bedrag} is still outstanding; the outstanding amount is {openstaand}.\n\nKind regards,\n{afzender}",
    "Rente over de te late betaling": "Interest on the late payment",
    "Buitengerechtelijke incassokosten": "Out-of-court collection costs",
