    "Stel je vraag, of laat weten waar de betaling vastloopt. Je bericht komt binnen bij Steffan zelf, op dezelfde plek als je andere projectvragen. Je hoort meestal binnen 1 werkdag iets.": "Ask your question, or let us know where the payment is stuck. Your message reaches Steffan himself, in the same place as your other project questions. You usually hear back within 1 working day.",
    "Je bericht": "Your message",
    "Vul eerst een bericht in.": "Please write a message first.",
    "Bedankt — je bericht is binnengekomen. Je hoort meestal binnen 1 werkdag iets.": "Thank you — your message has arrived. You usually hear back within 1 working day.",
    "Je bericht kon niet worden verstuurd. Probeer het zo nog eens, of mail steffan@customplus.nl.": "Your message could not be sent. Try again in a moment, or email steffan@customplus.nl.",
    "Deze pagina hoort bij één factuur en is alleen voor jou bedoeld. Deel de link niet — wie hem heeft, kan deze factuur bekijken.": "This page belongs to one invoice and is meant for you only. Do not share the link — anyone who has it can view this invoice.",
