    "Activiteit": "Activity",
    "Al overgemaakt? Meld het hier. Een melding is geen boeking: Steffan controleert je betaling en zet de factuur daarna op betaald.": "Already transferred? Report it here. A report is not a booking: Steffan checks your payment and then marks the invoice as paid.",
    "Alle {n} foto’s": "All {n} photos",
    "Alles is betaald.": "Everything has been paid.",
    "Alles wat dit portaal over jou en je producten bewaart, als één JSON-bestand: producten en fases, foto’s en documenten, facturen, samples, berichten, zendingen, je mensen en je herbestellingen. Zonder interne notities van CUSTOM+.": "Everything this portal keeps about you and your products, as one JSON file: products and phases, photos and documents, invoices, samples, messages, shipments, your people and your reorders. Without internal notes from CUSTOM+.",
    "Alles wat jou aangaat in dit product: updates van Steffan, je eigen handelingen, foto’s, berichten, betalingen en zendingen. Interne notities van CUSTOM+ staan hier niet.": "Everything that concerns you in this product: updates from Steffan, your own actions, photos, messages, payments and shipments. Internal notes from CUSTOM+ are not shown here.",
