    "Dit is een aanvraag: Steffan maakt de toegang aan en nodigt deze persoon per mail uit. Het vinkje zelf geeft nog geen login.": "This is a request: Steffan creates the access and invites this person by email. The checkbox itself does not grant a login yet.",
