    "Download alles": "Download everything",
    "Download alles geeft je een bestand met alles wat je in het portaal ziet: producten, documenten, facturen en gesprekken, zonder interne velden.": "Download everything gives you a file with everything you see in the portal: products, documents, invoices and conversations, without internal fields.",
    "Downloaden is hier nog niet beschikbaar.": "Downloading is not available here yet.",
    "Een creditnota vermindert wat je nog moet betalen. Het bedrag is al verrekend in de stand van de bijbehorende factuur.": "A credit note reduces what you still have to pay. The amount has already been settled in the balance of the related invoice.",
