    "Het portaal legt geen aparte inlogregel vast. Dit zijn de apparaten waarmee je iets deed in je product: een bestand bekeken of gedownload, een akkoord gegeven, een betaling gemeld.": "The portal does not record a separate login entry. These are the devices you used to do something in your product: view or download a file, give an approval, report a payment.",
