    "Je bent de hoofdcontactpersoon van dit account. De mails van CUSTOM+ komen op dit adres; wat je precies krijgt, stel je in onder Meldingen.": "You are the main contact of this account. CUSTOM+ emails go to this address; what exactly you receive, you set under Notifications.",
    "Je bericht komt in de Inbox van Steffan. Hij reageert meestal binnen 1 werkdag.": "Your message goes to Steffan’s inbox. He usually replies within 1 working day.",
