    "Je dossier wordt gedownload als JSON-bestand.": "Your records are being downloaded as a JSON file.",
    "Je dossier wordt samengesteld…": "Your records are being compiled…",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase. Alleen jij, via je login, en CUSTOM+ kunnen erbij.": "Your data is stored in the CUSTOM+ database at Supabase. Only you, through your login, and CUSTOM+ can access it.",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase. Elke rij is met toegangsregels beperkt tot je eigen klantaccount: alleen jij, via je login, en CUSTOM+ kunnen erbij.": "Your data is stored in the CUSTOM+ database at Supabase. Every row is restricted by access rules to your own client account: only you, through your login, and CUSTOM+ can access it.",
    "Je hebt een vraag over deze factuur gesteld. Steffan neemt contact met je op; tot die tijd staan de herinneringen stil en hoef je niets te doen.": "You have asked a question about this invoice. Steffan will contact you; until then the reminders are paused and you do not need to do anything.",
    "Je huidige voorkeuren konden niet worden geladen; hieronder staat de standaard.": "Your current preferences could not be loaded; the default is shown below.",
    "Je keuze geldt meteen voor dit portaal en wordt bewaard als jouw voorkeur bij CUSTOM+.": "Your choice applies to this portal immediately and is saved as your preference with CUSTOM+.",
    "Je kijkt mee als beheerder. In de voorvertoning kun je hier niets wijzigen; wat je aanpast wordt niet bewaard.": "You are viewing as an administrator. In the preview you cannot change anything here; whatever you adjust is not saved.",
    "Je kijkt naar de tijdlijn van het product dat nu open staat. Een ander product kies je via Producten.": "You are looking at the timeline of the product that is currently open. You choose another product via Products.",
