    "Je vraag komt in de Inbox van Steffan. Hij leest en beantwoordt elk bericht zelf, meestal binnen 1 werkdag.": "Your question goes to Steffan’s inbox. He reads and answers every message himself, usually within 1 working day.",
    "Je werkt in de demo. Alles wat je hier doet staat alleen in deze browser en verdwijnt zodra je de browsergegevens wist.": "You are working in the demo. Everything you do here is stored only in this browser and disappears as soon as you clear your browser data.",
    "Je werkt in de demo. Alles wat je hier doet staat alleen in deze browser, in de browseropslag die het portaal en het beheer op dit apparaat delen. Het verdwijnt zodra je de browsergegevens wist en bereikt geen server.": "You are working in the demo. Everything you do here is stored only in this browser, in the browser storage that the portal and the admin share on this device. It disappears as soon as you clear your browser data and never reaches a server.",
