    "Vier onderdelen: je mensen, je meldingen, je taal en je gegevens. Bij je mensen en je meldingen staan wijzigingen pas vast als je ze opslaat; je krijgt een waarschuwing als je met onopgeslagen werk wegloopt.": "Four sections: your people, your notifications, your language and your data. For your people and your notifications, changes are only final once you save them; you get a warning if you leave with unsaved work.",
