    "Alles wat jou aangaat in dit product: updates, foto’s, berichten, betalingen en zendingen.": "Everything that concerns you in this product: updates, photos, messages, payments and shipments.",
    "Ook je eigen handelingen staan erin: een akkoord, een samplekeuze, een gemelde betaling, een download.": "Your own actions are in it too: an approval, a sample decision, a reported payment, a download.",
