    "Je kijkt naar de tijdlijn van het product dat nu open staat.": "You are looking at the timeline of the product that is currently open.",
    "De mails van CUSTOM+ komen op dit adres.": "CUSTOM+ emails go to this address.",
    "Je bent de hoofdcontactpersoon van dit account; wat je precies krijgt, stel je in onder Meldingen.": "You are the main contact of this account; what exactly you receive, you set under Notifications.",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase; alleen jij en CUSTOM+ kunnen erbij.": "Your data is stored in the CUSTOM+ database at Supabase; only you and CUSTOM+ can access it.",
    "Elke rij is met toegangsregels beperkt tot je eigen klantaccount, via je login.": "Every row is restricted by access rules to your own client account, through your login.",
    "Je werkt in de demo: alles staat alleen in deze browser en bereikt geen server.": "You are working in the demo: everything is stored only in this browser and never reaches a server.",
    "Het portaal en het beheer delen op dit apparaat dezelfde browseropslag; alles verdwijnt zodra je de browsergegevens wist.": "The portal and the admin share the same browser storage on this device; everything disappears as soon as you clear your browser data.",
    "Je mensen, je meldingen, je taal en je gegevens.": "Your people, your notifications, your language and your data.",
    "Bij je mensen en je meldingen staan wijzigingen pas vast als je ze opslaat; loop je weg met onopgeslagen werk, dan krijg je een waarschuwing.": "For your people and your notifications, changes are only final once you save them; if you leave with unsaved work, you get a warning.",
    "Je kijkt mee als beheerder: in de voorvertoning wordt niets bewaard.": "You are viewing as an administrator: nothing is saved in the preview.",
    "Dit vinkje is een aanvraag: Steffan maakt de toegang aan en nodigt deze persoon per mail uit.": "This checkbox is a request: Steffan creates the access and invites this person by email.",
    "De lijst met je mensen kon niet worden geladen; vernieuw de pagina.": "The list of your people could not be loaded; refresh the page.",
    "Per persoon kies je welke soorten mail iemand krijgt; jouw eigen mails regel je onder Meldingen.": "Per person you choose which email types they receive; your own emails you set under Notifications.",
    "Iemand zonder soorten krijgt geen mail; iedereen met een login ziet alles in dit portaal.": "Someone without any types receives no email; everyone with a login sees everything in this portal.",
    "Je meldingen konden niet worden geladen; vernieuw de pagina.": "Your notifications could not be loaded; refresh the page.",
    "De mails gaan naar het adres waarmee je inlogt.": "The emails go to the address you sign in with.",
    "Zet je een soort uit, dan stuurt CUSTOM+ die mails niet meer; in het portaal zie je alles nog gewoon.": "If you switch a type off, CUSTOM+ no longer sends those emails; in the portal you still see everything as usual.",
    "Welke mail je collega’s krijgen, regel je per persoon onder Jouw mensen.": "Which emails your colleagues receive, you set per person under Your people.",
    "Je keuze geldt meteen voor dit portaal; je mails komen in het Nederlands of anders in het Engels.": "Your choice applies to this portal right away; your emails come in Dutch or otherwise in English.",
    "De keuze wordt bewaard als jouw voorkeur bij CUSTOM+.": "The choice is saved as your preference at CUSTOM+.",
    "De mails van CUSTOM+ bestaan alleen in het Nederlands en het Engels; kies je een andere taal, dan komen je mails in het Engels.": "CUSTOM+ emails exist only in Dutch and English; if you choose another language, your emails come in English.",
    "Het portaal legt geen inlogmoment vast; wat het wél vastlegt is een bestand bekijken of downloaden, een akkoord geven, een betaling melden.": "The portal does not record a login moment; what it does record is viewing or downloading a file, giving an approval, reporting a payment.",
    "De apparaten waarmee je zelf iets deed in {product}; een aparte inlogregel is er niet.": "The devices you used to do something in {product}; there is no separate login entry.",
    "De apparaten waarmee je zelf iets deed in je product; een aparte inlogregel is er niet.": "The devices you used to do something in your product; there is no separate login entry.",
    "Alles wat dit portaal over jou bewaart als één JSON-bestand, zonder de foto’s en PDF’s zelf.": "Everything this portal keeps about you as one JSON file, without the photos and PDFs themselves.",
    "Erin: producten en fases, foto’s en documenten, facturen, samples, berichten, zendingen, je mensen en je herbestellingen; zonder interne notities van CUSTOM+.": "Included: products and phases, photos and documents, invoices, samples, messages, shipments, your people and your reorders; without internal notes from CUSTOM+.",
    "De bestanden zelf download je per stuk onder Bestanden.": "The files themselves you download one by one under Files.",
    "Wat er wordt vastgelegd: wanneer je een bestand bekijkt of downloadt, en elke handeling die je in dit portaal doet — een akkoord, een samplekeuze, een gemelde betaling, een bericht, een upload; dat logboek lees je zelf onder Activiteit.": "What is recorded: when you view or download a file, and every action you take in this portal — an approval, a sample decision, a reported payment, a message, an upload; you can read that log yourself under Activity.",
