    "Je idee wordt uitgewerkt tot een ontwerp dat echt te maken is; dit duurt meestal 1 tot 2 weken.": "Your idea is worked out into a design that can really be made; this usually takes 1 to 2 weeks.",
    "Het ontwerp wordt doorgerekend voor de fabriek, zodat het zonder verrassingen te produceren is; dit duurt meestal 2 tot 4 weken.": "The design is worked through for the factory, so it can be produced without surprises; this usually takes 2 to 4 weeks.",
    "We kiezen en controleren de fabriek die bij je product past en leggen de afspraken vast; dit duurt meestal 2 tot 3 weken.": "We choose and check the factory that suits your product and put the agreements in writing; this usually takes 2 to 3 weeks.",
