    "Elke inspectie wordt gemeten tegen de AQL norm uit je offerte. De eerste controle staat gepland in fase {p} van {t} — jullie zitten nu in fase {c}, {fase}.": "Jede Inspektion wird an der AQL Norm aus Ihrem Angebot gemessen. Die erste Kontrolle ist in Phase {p} von {t} geplant — Sie sind jetzt in Phase {c}, {fase}.",
    "De productie loopt. Het eerste inspectierapport verschijnt hier zodra de controle tegen de AQL norm is uitgevoerd.": "Die Produktion läuft. Der erste Inspektionsbericht erscheint hier, sobald die Kontrolle gegen die AQL Norm durchgeführt ist.",
    "Zodra er een inspectie is uitgevoerd, staat het rapport hier — gemeten tegen de AQL norm uit je offerte.": "Sobald eine Inspektion durchgeführt ist, steht der Bericht hier — gemessen an der AQL Norm aus Ihrem Angebot.",
    "Stel een vraag over deze foto": "Stellen Sie eine Frage zu diesem Foto",
