    "van fabriek tot deur": "von der Fabrik bis zur Tür",
    "Samples per koerier en je productie per zeevracht, elk met hun eigen mijlpalen. Geleverde zendingen blijven hier permanent staan.": "Muster per Kurier und Ihre Produktion per Seefracht, jeweils mit eigenen Meilensteinen. Gelieferte Sendungen bleiben hier dauerhaft stehen.",
