    "Deze indicatie is ouder dan een week. Steffan werkt hem bij zodra er nieuws van de vervoerder is.": "Diese Angabe ist älter als eine Woche. Steffan aktualisiert sie, sobald es Neuigkeiten vom Frachtführer gibt.",
    "Volg {nr}": "Verfolgen Sie {nr}",
