    /* FIXRONDE R0-5/R1-5 + R1-6: document zonder geüpload bestand en de
       route van het betaalpad naar het factuurdocument */
    "PDF volgt": "PDF folgt",
    "Het bestand wordt nog toegevoegd.": "Die Datei wird noch hinzugefügt.",
    "Nog geen bestand": "Noch keine Datei",
    "Dit document is al aangemaakt, maar het bestand staat er nog niet bij. Zodra Steffan het toevoegt, verschijnt de download hier — opnieuw proberen helpt nu niet.": "Dieses Dokument ist bereits angelegt, die Datei fehlt aber noch. Sobald Steffan sie hinzufügt, erscheint der Download hier — ein erneuter Versuch hilft jetzt nicht.",
    "Bekijk het factuurdocument": "Rechnungsdokument ansehen",
    "Zodra er een zending is, begint hier de reis": "Sobald es eine Sendung gibt, beginnt hier die Reise",
    "Samples reizen per koerier, je productiebatch per zeevracht — elke zending krijgt hier zijn eigen reis met mijlpalen.": "Muster reisen per Kurier, Ihre Produktionscharge per Seefracht — jede Sendung bekommt hier ihre eigene Reise mit Meilensteinen.",
    "Er is nu niets onderweg. Alles wat eerder is verzonden staat hieronder in het archief.": "Derzeit ist nichts unterwegs. Alles früher Versandte steht unten im Archiv.",
    "Archief · {y} — geleverde zendingen blijven hier permanent staan": "Archiv · {y} — gelieferte Sendungen bleiben hier dauerhaft stehen",
    "Alles op één plek": "Alles an einem Ort",
    "Contracten, offertes, facturen en rapporten, geordend per fase. Elke download wordt in het logboek genoteerd.": "Verträge, Angebote, Rechnungen und Berichte, geordnet je Phase. Jeder Download wird im Logbuch vermerkt.",
    "Demo-omgeving": "Demo-Umgebung",
    "In de demo staat hier het echte bestand. In je eigen omgeving opent de download direct, via een beveiligde link die 15 minuten geldig is.": "In der Demo stünde hier die echte Datei. In Ihrer eigenen Umgebung öffnet der Download direkt, über einen gesicherten Link mit 15 Minuten Gültigkeit.",
    "Bestand niet beschikbaar in deze browser": "Datei in diesem Browser nicht verfügbar",
    "Dit bestand staat in de browseropslag van de computer waarop het is geüpload en reist niet mee naar andere browsers. Open het portaal daar, of mail steffan@customplus.nl.": "Diese Datei liegt im Browserspeicher des Computers, auf dem sie hochgeladen wurde, und wandert nicht in andere Browser mit. Öffnen Sie das Portal dort, oder schreiben Sie an steffan@customplus.nl.",
    "Deze download is wel in je toegangslogboek genoteerd, zodat je ziet hoe dat werkt.": "Dieser Download wurde in Ihrem Zugriffslogbuch vermerkt, damit Sie sehen, wie das funktioniert.",
    "Het bestand kon nu niet worden opgehaald. Probeer het over een minuut opnieuw of mail steffan@customplus.nl.": "Die Datei konnte gerade nicht abgerufen werden. Versuchen Sie es in einer Minute erneut oder schreiben Sie an steffan@customplus.nl.",
    "Zodra Steffan het eerste document deelt — meestal de NNN overeenkomst — staat het hier, geordend per fase en permanent bewaard.": "Sobald Steffan das erste Dokument teilt — meist die NNN Vereinbarung — steht es hier, geordnet je Phase und dauerhaft aufbewahrt.",
    "Wordt verwacht in deze fase": "Wird in dieser Phase erwartet",
    "Verschijnt hier zodra Steffan het deelt.": "Erscheint hier, sobald Steffan es teilt.",
