    /* D2 — kosten, logboek, meldingen, vaktaal */
    "Het betaalpad": "Der Zahlungspfad",
    "Betalen per mijlpaal": "Zahlen je Meilenstein",
    "Je keurt elke fase goed vóór je betaalt. Hieronder staat wat is betaald, wat openstaat en wat er nog volgt — elk bedrag komt van een echte factuur.": "Sie geben jede Phase frei, bevor Sie zahlen. Unten steht, was bezahlt ist, was offensteht und was noch folgt — jeder Betrag stammt aus einer echten Rechnung.",
