    "Betaal-QR voor factuur {n}": "Zahlungs-QR-Code für Rechnung {n}",
    "Scan met je bank-app": "Mit Ihrer Banking-App scannen",
    "Scan de code met je bank-app: bedrag en kenmerk staan er al in. Liever handmatig? Neem dan bovenstaande gegevens over en vermeld het kenmerk.": "Scannen Sie den Code mit Ihrer Banking-App: Betrag und Verwendungszweck sind bereits enthalten. Lieber manuell? Übernehmen Sie dann die oben stehenden Angaben und geben Sie den Verwendungszweck an.",
    "Vermeld het kenmerk bij je overboeking — daarmee wordt je betaling meteen aan deze factuur gekoppeld.": "Geben Sie den Verwendungszweck bei Ihrer Überweisung an — so wird Ihre Zahlung sofort dieser Rechnung zugeordnet.",
    "Deze factuur staat niet in euro. Maak over via SWIFT met bovenstaande gegevens en vermeld het kenmerk.": "Diese Rechnung lautet nicht auf Euro. Überweisen Sie per SWIFT mit den oben stehenden Angaben und geben Sie den Verwendungszweck an.",
    "Vermeld bij de overboeking het kenmerk {n} — daarmee wordt je betaling meteen aan deze factuur gekoppeld.": "Geben Sie bei der Überweisung den Verwendungszweck {n} an — so wird Ihre Zahlung sofort dieser Rechnung zugeordnet.",
    "Vermeld bij de overboeking het kenmerk {n}. Deze factuur staat niet in euro; maak over via SWIFT met bovenstaande gegevens.": "Geben Sie bei der Überweisung den Verwendungszweck {n} an. Diese Rechnung lautet nicht auf Euro; überweisen Sie per SWIFT mit den oben stehenden Angaben.",
