    "Omrekenkoers vastgelegd op de factuurdatum: 1 EUR = {r} {c}. De administratie rekent uitsluitend met deze koers.": "Umrechnungskurs zum Rechnungsdatum festgelegt: 1 EUR = {r} {c}. Die Buchhaltung rechnet ausschließlich mit diesem Kurs.",
    "Factuur {n} ({b}) staat klaar op je betaalpad. Vermeld bij de betaling het kenmerk {n}.": "Rechnung {n} ({b}) liegt auf Ihrem Zahlungspfad bereit. Geben Sie bei der Zahlung den Verwendungszweck {n} an.",
    "Betaald": "Bezahlt",
