    "Zie de factuur hieronder.": "Siehe Rechnung unten.",
    "Er zijn nog geen betaalmomenten vastgelegd.": "Es sind noch keine Zahlungsmeilensteine festgelegt.",
    "Alle betaalmomenten zijn gefactureerd.": "Alle Zahlungsmeilensteine sind in Rechnung gestellt.",
    "{p}% van de projectsom, verdeeld over 1 betaalmoment.": "{p}% der Projektsumme, in 1 Zahlungsmeilenstein.",
