    "Van de projectsom, volgens je mijlpalenpad. Het bedrag staat op de factuur zodra die er is.": "Der Projektsumme, gemäß Ihrem Meilensteinpfad. Der Betrag steht auf der Rechnung, sobald es sie gibt.",
