    ", fase goedgekeurd": ", Phase freigegeben",
    "Vol = goedgekeurd en betaald · gearceerd = gefactureerd, staat open · omlijnd = nog niet aan de orde": "Gefüllt = freigegeben und bezahlt · schraffiert = in Rechnung gestellt, offen · umrandet = noch nicht fällig",
