    "en wanneer": "und wann",
    "Jouw bestanden zijn van jou. Dit logboek laat zien wat ermee is gebeurd.": "Ihre Dateien gehören Ihnen. Dieses Logbuch zeigt, was mit ihnen geschehen ist.",
    "Dit logboek toont elke keer dat een bestand van dit project is bekeken, gedownload of gedeeld.": "Dieses Logbuch zeigt jedes Mal, wenn eine Datei dieses Projekts angesehen, heruntergeladen oder geteilt wurde.",
    "Jij bekeek ‘{x}’": "Sie haben ‘{x}’ angesehen",
