    "Nog geen activiteit.": "Noch keine Aktivität.",
    "Je bent helemaal bij.": "Sie sind auf dem neuesten Stand.",
    "Nieuwe foto: {x}": "Neues Foto: {x}",
    "update uit de fabriek": "Update aus der Fabrik",
    "FASE {n}": "PHASE {n}",
    "ANTWOORD": "ANTWORT",
    "Steffan beantwoordde je vraag: ‘{x}’": "Steffan hat Ihre Frage beantwortet: ‘{x}’",
    "Nieuw document: {x}": "Neues Dokument: {x}",
    "FACTUUR": "RECHNUNG",
    "Factuur betaald: {x}": "Rechnung bezahlt: {x}",
    "Er staat een factuur voor je klaar: {x}": "Eine Rechnung liegt für Sie bereit: {x}",
    "Zending: {x}": "Sendung: {x}",
    "goedgekeurd": "freigegeben",
    "Uitleg: {term}": "Erklärung: {term}",
    "Lees meer op de site": "Mehr auf der Website lesen",
    "De statistische norm die bepaalt hoeveel afwijkingen een steekproef mag bevatten voordat de hele batch wordt afgekeurd. Elke inspectie in je portaal wordt tegen deze norm gemeten.": "Die statistische Norm, die festlegt, wie viele Abweichungen eine Stichprobe enthalten darf, bevor die ganze Charge abgelehnt wird. Jede Inspektion in Ihrem Portal wird an dieser Norm gemessen.",
    "Een contract dat is opgesteld om afdwingbaar te zijn bij Chinese rechtbanken, getekend vóór er één bestand de deur uit gaat. Een westerse NDA alleen is dat in de praktijk vaak niet.": "Ein Vertrag, der so aufgesetzt ist, dass er vor chinesischen Gerichten durchsetzbar ist, unterzeichnet, bevor auch nur eine Datei das Haus verlässt. Ein westliches NDA allein ist das in der Praxis oft nicht.",
    "De stap waarin je ontwerp wordt getoetst aan het productieproces dat het echt gaat maken, vóór er tooling wordt besteld. Een mooi CAD bestand en een maakbaar onderdeel zijn niet hetzelfde.": "Der Schritt, in dem Ihr Design am Produktionsprozess geprüft wird, der es wirklich fertigen wird, bevor Tooling bestellt wird. Eine schöne CAD Datei und ein fertigbares Teil sind nicht dasselbe.",
    "De kleinste oplage die een fabriek wil draaien. Voor spuitgietwerk ligt die doorgaans hoger dan voor CNC of plaatwerk, omdat de mal moet worden terugverdiend.": "Die kleinste Auflage, die eine Fabrik fahren will. Beim Spritzguss liegt sie meist höher als bei CNC oder Blech, weil sich das Werkzeug amortisieren muss.",
    "De controle van binnenkomend materiaal vóórdat de productie start, zodat een afwijking in de grondstof nooit een hele run kan raken.": "Die Kontrolle des eingehenden Materials, bevor die Produktion startet, damit eine Abweichung im Rohstoff nie einen ganzen Lauf treffen kann.",
    "Controles tijdens de productierun zelf, niet pas aan het einde — zo wordt een afwijking gevonden terwijl die nog goedkoop te herstellen is.": "Kontrollen während des Produktionslaufs selbst, nicht erst am Ende — so wird eine Abweichung gefunden, solange sie noch günstig zu beheben ist.",
    "De eindcontrole op de afgeronde batch, vlak vóór verzending, gemeten tegen hetzelfde golden sample waarmee de run begon.": "Die Endkontrolle der fertigen Charge, kurz vor dem Versand, gemessen an demselben golden sample, mit dem der Lauf begann.",
    "Het allereerste schot uit een nieuwe mal. Een T0 is zelden meteen goed — deze ronde laat zien wat er aan de mal moet worden bijgesteld.": "Der allererste Schuss aus einem neuen Werkzeug. Ein T0 ist selten sofort gut — diese Runde zeigt, was am Werkzeug nachjustiert werden muss.",
    "De sampleronde na de eerste bijstelling van de mal. Elke volgende ronde brengt het sample dichter bij het exemplaar dat jij goedkeurt.": "Die Musterrunde nach der ersten Nachjustierung des Werkzeugs. Jede weitere Runde bringt das Sample näher an das Exemplar, das Sie freigeben.",
    "De ronde na de tweede bijstelling, vaak de laatste verfijning zoals polijstwerk aan de mal. Keur jij deze goed, dan wordt dit exemplaar meestal het golden sample.": "Die Runde nach der zweiten Nachjustierung, oft der letzte Feinschliff wie Polierarbeit am Werkzeug. Geben Sie sie frei, wird dieses Exemplar meist das golden sample.",
    "Het sample dat jij goedkeurt als dé standaard. Elke inspectie tijdens de productie meet de batch tegen precies dit exemplaar — niet tegen een gevoel.": "Das Sample, das Sie als den Standard freigeben. Jede Inspektion während der Produktion misst die Charge an genau diesem Exemplar — nicht an einem Gefühl.",
    "Het officiële vervoersdocument van een zeevracht: het bewijs dat de lading aan boord is én het document waarmee de container op de bestemming wordt vrijgegeven.": "Das offizielle Transportdokument einer Seefracht: der Nachweis, dass die Ladung an Bord ist, und das Dokument, mit dem der Container am Ziel freigegeben wird.",
    /* factuurmodule fase 5 — de herinneringsteksten */
    "Herinnering: factuur {nummer} vervalt {vervaldatum}": "Erinnerung: Rechnung {nummer} ist am {vervaldatum} fällig",
    "Beste {naam},\n\nEen vriendelijke herinnering: factuur {nummer} van {bedrag} vervalt op {vervaldatum}.\n\nIs de betaling al onderweg, dan kun je dit bericht als niet verzonden beschouwen.\n\nMet vriendelijke groet,\n{afzender}": "Guten Tag {naam},\n\neine freundliche Erinnerung: Rechnung {nummer} über {bedrag} ist am {vervaldatum} fällig.\n\nFalls die Zahlung bereits unterwegs ist, betrachten Sie diese Nachricht bitte als gegenstandslos.\n\nMit freundlichen Grüßen,\n{afzender}",
    "Factuur {nummer} staat nog open": "Rechnung {nummer} ist noch offen",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} is op {vervaldatum} vervallen en staat nog open. Waarschijnlijk is het je ontgaan.\n\nHet openstaande bedrag is {openstaand}. Klopt er iets niet, laat het dan weten — dan lossen we het samen op.\n\nMet vriendelijke groet,\n{afzender}": "Guten Tag {naam},\n\nRechnung {nummer} über {bedrag} war am {vervaldatum} fällig und ist noch offen. Wahrscheinlich ist sie Ihnen entgangen.\n\nDer offene Betrag beträgt {openstaand}. Sollte etwas nicht stimmen, sagen Sie es uns bitte — dann klären wir das gemeinsam.\n\nMit freundlichen Grüßen,\n{afzender}",
    "Tweede herinnering: factuur {nummer}": "Zweite Erinnerung: Rechnung {nummer}",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} staat sinds {vervaldatum} open. Het openstaande bedrag is {openstaand}.\n\nWe hebben nog geen betaling ontvangen en ook geen bericht. Wil je de betaling deze week in orde maken, of laten weten waar het aan ligt?\n\nMet vriendelijke groet,\n{afzender}": "Guten Tag {naam},\n\nRechnung {nummer} über {bedrag} ist seit {vervaldatum} offen. Der offene Betrag beträgt {openstaand}.\n\nWir haben weder eine Zahlung noch eine Nachricht erhalten. Können Sie die Zahlung diese Woche veranlassen oder uns mitteilen, woran es liegt?\n\nMit freundlichen Grüßen,\n{afzender}",
    "Laatste aanmaning: factuur {nummer}": "Letzte Mahnung: Rechnung {nummer}",
    "Beste {naam},\n\nOndanks eerdere herinneringen staat factuur {nummer} nog open. Het openstaande bedrag is {openstaand}, vervallen op {vervaldatum}.\n\nDit is de laatste aanmaning. Zonder betaling of bericht binnen veertien dagen dragen we de vordering over.\n\nMet vriendelijke groet,\n{afzender}": "Guten Tag {naam},\n\ntrotz früherer Erinnerungen ist Rechnung {nummer} noch offen. Der offene Betrag beträgt {openstaand}, fällig seit {vervaldatum}.\n\nDies ist die letzte Mahnung. Ohne Zahlung oder Nachricht innerhalb von vierzehn Tagen geben wir die Forderung ab.\n\nMit freundlichen Grüßen,\n{afzender}",
    "Over factuur {nummer}": "Zu Rechnung {nummer}",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} staat nog open; het openstaande bedrag is {openstaand}.\n\nMet vriendelijke groet,\n{afzender}": "Guten Tag {naam},\n\nRechnung {nummer} über {bedrag} ist noch offen; der offene Betrag beträgt {openstaand}.\n\nMit freundlichen Grüßen,\n{afzender}",
    "Rente over de te late betaling": "Zinsen wegen verspäteter Zahlung",
    "Buitengerechtelijke incassokosten": "Außergerichtliche Inkassokosten",
    /* factuurmodule fase 4 — de beveiligde klantpagina (factuur.html) */
    "Bekijk je factuur": "Rechnung ansehen",
