    "Deze link is niet bekend. Controleer of je hem volledig hebt gekopieerd — hij is lang en breekt makkelijk af in een e-mail.": "Dieser Link ist nicht bekannt. Prüfen Sie, ob Sie ihn vollständig kopiert haben — er ist lang und bricht in einer E-Mail leicht um.",
