    "Vraag of betaalprobleem melden": "Frage oder Zahlungsproblem melden",
    "Stel je vraag, of laat weten waar de betaling vastloopt. Je bericht komt binnen bij Steffan zelf, op dezelfde plek als je andere projectvragen. Je hoort meestal binnen 1 werkdag iets.": "Stellen Sie Ihre Frage oder sagen Sie uns, wo die Zahlung hakt. Ihre Nachricht erreicht Steffan persönlich, an derselben Stelle wie Ihre anderen Projektfragen. Sie hören meist innerhalb von 1 Werktag von ihm.",
    "Je bericht": "Ihre Nachricht",
    "Vul eerst een bericht in.": "Bitte schreiben Sie zuerst eine Nachricht.",
    "Bedankt — je bericht is binnengekomen. Je hoort meestal binnen 1 werkdag iets.": "Danke — Ihre Nachricht ist angekommen. Sie hören meist innerhalb von 1 Werktag von uns.",
    "Je bericht kon niet worden verstuurd. Probeer het zo nog eens, of mail steffan@customplus.nl.": "Ihre Nachricht konnte nicht gesendet werden. Versuchen Sie es gleich noch einmal oder schreiben Sie an steffan@customplus.nl.",
    "Deze pagina hoort bij één factuur en is alleen voor jou bedoeld. Deel de link niet — wie hem heeft, kan deze factuur bekijken.": "Diese Seite gehört zu einer Rechnung und ist nur für Sie bestimmt. Teilen Sie den Link nicht — wer ihn hat, kann diese Rechnung einsehen.",
    /* klantportaal 2026-09 — hoofdstuk: schermen, acties, foutzinnen */
    "1 contactpersoon": "1 Ansprechpartner",
    "1 gebeurtenis": "1 Ereignis",
    "1 gesprek wacht op je": "1 Gespräch wartet auf Sie",
    "1 open factuur": "1 offene Rechnung",
    "Aangeleverd door jou": "Von Ihnen bereitgestellt",
    "Aangemaakt op {datum}": "Angelegt am {datum}",
    "Activiteit": "Aktivität",
    "Al overgemaakt? Meld het hier. Een melding is geen boeking: Steffan controleert je betaling en zet de factuur daarna op betaald.": "Schon überwiesen? Melden Sie es hier. Eine Meldung ist keine Buchung: Steffan prüft Ihre Zahlung und setzt die Rechnung danach auf bezahlt.",
    "Alle {n} foto’s": "Alle {n} Fotos",
    "Alles is betaald.": "Alles ist bezahlt.",
    "Alles wat dit portaal over jou en je producten bewaart, als één JSON-bestand: producten en fases, foto’s en documenten, facturen, samples, berichten, zendingen, je mensen en je herbestellingen. Zonder interne notities van CUSTOM+.": "Alles, was dieses Portal über Sie und Ihre Produkte speichert, als eine JSON-Datei: Produkte und Phasen, Fotos und Dokumente, Rechnungen, Samples, Nachrichten, Sendungen, Ihr Team und Ihre Nachbestellungen. Ohne interne Notizen von CUSTOM+.",
    "Alles wat jou aangaat in dit product: updates van Steffan, je eigen handelingen, foto’s, berichten, betalingen en zendingen. Interne notities van CUSTOM+ staan hier niet.": "Alles, was Sie in diesem Produkt betrifft: Updates von Steffan, Ihre eigenen Handlungen, Fotos, Nachrichten, Zahlungen und Sendungen. Interne Notizen von CUSTOM+ stehen hier nicht.",
