    "De bestanden zelf — de foto’s en PDF’s — zitten er niet in; die download je per stuk onder Bestanden.": "Die Dateien selbst — die Fotos und PDFs — sind nicht enthalten; die laden Sie einzeln unter Dateien herunter.",
    "De lijst met je mensen kon niet worden geladen.": "Die Liste Ihres Teams konnte nicht geladen werden.",
    "De mails van CUSTOM+ bestaan in het Nederlands en het Engels. Kies je een andere taal, dan komen je mails in het Engels.": "Die E-Mails von CUSTOM+ gibt es auf Niederländisch und Englisch. Wählen Sie eine andere Sprache, kommen Ihre E-Mails auf Englisch.",
