    "Dit bestand is groter dan 25 MB. Kies een kleiner bestand.": "Diese Datei ist größer als 25 MB. Wählen Sie eine kleinere Datei.",
    "Dit e-mailadres ziet er niet goed uit.": "Diese E-Mail-Adresse sieht nicht richtig aus.",
    "Dit is een aanvraag: Steffan maakt de toegang aan en nodigt deze persoon per mail uit. Het vinkje zelf geeft nog geen login.": "Dies ist eine Anfrage: Steffan richtet den Zugang ein und lädt diese Person per E-Mail ein. Das Häkchen allein gibt noch keinen Login.",
    "Dit is een demo-account.": "Dies ist ein Demo-Konto.",
