    "Dit onderdeel wordt nog gebouwd.": "Dieser Bereich wird noch gebaut.",
    "Dit onderdeel wordt nog gebouwd. Je taal kies je in het gebruikersmenu rechtsboven; daar staat ook Download alles.": "Dieser Bereich wird noch gebaut. Ihre Sprache wählen Sie im Benutzermenü oben rechts; dort finden Sie auch Alles herunterladen.",
    "Dit overzicht hoort bij het product dat nu open staat; wissel van product om een ander logboek te zien.": "Diese Übersicht gehört zum aktuell geöffneten Produkt; wechseln Sie das Produkt, um ein anderes Logbuch zu sehen.",
    "Dit product kon niet worden gevonden.": "Dieses Produkt wurde nicht gefunden.",
    "Dit zijn jouw eigen mails. Welke mail je collega’s krijgen, regel je per persoon onder Jouw mensen.": "Dies sind Ihre eigenen E-Mails. Welche E-Mails Ihre Kollegen erhalten, legen Sie je Person unter Ihr Team fest.",
    "Download alles": "Alles herunterladen",
    "Download alles geeft je een bestand met alles wat je in het portaal ziet: producten, documenten, facturen en gesprekken, zonder interne velden.": "Alles herunterladen gibt Ihnen eine Datei mit allem, was Sie im Portal sehen: Produkte, Dokumente, Rechnungen und Gespräche, ohne interne Felder.",
    "Downloaden is hier nog niet beschikbaar.": "Herunterladen ist hier noch nicht verfügbar.",
    "Een creditnota vermindert wat je nog moet betalen. Het bedrag is al verrekend in de stand van de bijbehorende factuur.": "Eine Gutschrift verringert, was Sie noch zahlen müssen. Der Betrag ist bereits im Stand der zugehörigen Rechnung verrechnet.",
    "Elk bestandstype kan, tot {mb} MB — bijvoorbeeld PDF, JPG, PNG, AI of ZIP.": "Jeder Dateityp ist möglich, bis {mb} MB — zum Beispiel PDF, JPG, PNG, AI oder ZIP.",
    "Elke factuur die Steffan publiceert, staat hier met haar stand, vervaldatum en betaalgegevens.": "Jede Rechnung, die Steffan veröffentlicht, steht hier mit ihrem Stand, Fälligkeitsdatum und den Zahlungsdaten.",
    "Er is wel activiteit van andere soorten. Kies “Alles” om de volledige tijdlijn te zien.": "Es gibt Aktivität anderer Art. Wählen Sie „Alles“, um die vollständige Zeitleiste zu sehen.",
