    "Het adres wijst naar iets wat het portaal niet kent.": "Die Adresse verweist auf etwas, das das Portal nicht kennt.",
    "Het factuurnummer, of de omschrijving die je bij je bank hebt gebruikt.": "Die Rechnungsnummer oder der Verwendungszweck, den Sie bei Ihrer Bank angegeben haben.",
    "Het hoort niet bij jouw account, of het bestaat niet meer.": "Es gehört nicht zu Ihrem Konto, oder es existiert nicht mehr.",
    "Het portaal legt geen aparte inlogregel vast. Dit zijn de apparaten waarmee je iets deed in je product: een bestand bekeken of gedownload, een akkoord gegeven, een betaling gemeld.": "Das Portal hält keinen eigenen Login-Eintrag fest. Dies sind die Geräte, mit denen Sie etwas in Ihrem Produkt getan haben: eine Datei angesehen oder heruntergeladen, eine Freigabe erteilt, eine Zahlung gemeldet.",
    "Hoofdcontactpersoon — logt in en ontvangt de mails die je onder Meldingen aanzet.": "Hauptansprechpartner — meldet sich an und erhält die E-Mails, die Sie unter Mitteilungen einschalten.",
    "In de voorvertoning wisselt alleen dit scherm van taal; de voorkeur van de klant blijft staan.": "In der Vorschau wechselt nur dieser Bildschirm die Sprache; die Einstellung des Kunden bleibt bestehen.",
    "In {valuta}, bijvoorbeeld 1234,56": "In {valuta}, zum Beispiel 1234,56",
    "Ingelogd als hoofdcontactpersoon van dit account.": "Angemeldet als Hauptansprechpartner dieses Kontos.",
    "Instellingen": "Einstellungen",
    "Ja, verwijderen": "Ja, löschen",
    "Je bent de hoofdcontactpersoon van dit account. De mails van CUSTOM+ komen op dit adres; wat je precies krijgt, stel je in onder Meldingen.": "Sie sind der Hauptansprechpartner dieses Kontos. Die E-Mails von CUSTOM+ gehen an diese Adresse; was genau Sie erhalten, stellen Sie unter Mitteilungen ein.",
    "Je bericht komt in de Inbox van Steffan. Hij reageert meestal binnen 1 werkdag.": "Ihre Nachricht landet im Posteingang von Steffan. Er antwortet meist innerhalb von 1 Werktag.",
    "Je betaling is gemeld.": "Ihre Zahlung wurde gemeldet.",
    "Je dossier wordt gedownload als JSON-bestand.": "Ihre Akte wird als JSON-Datei heruntergeladen.",
    "Je dossier wordt samengesteld…": "Ihre Akte wird zusammengestellt …",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase. Alleen jij, via je login, en CUSTOM+ kunnen erbij.": "Ihre Daten liegen in der Datenbank von CUSTOM+ bei Supabase. Nur Sie, über Ihren Login, und CUSTOM+ haben Zugriff.",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase. Elke rij is met toegangsregels beperkt tot je eigen klantaccount: alleen jij, via je login, en CUSTOM+ kunnen erbij.": "Ihre Daten liegen in der Datenbank von CUSTOM+ bei Supabase. Jede Zeile ist durch Zugriffsregeln auf Ihr eigenes Kundenkonto beschränkt: Nur Sie, über Ihren Login, und CUSTOM+ haben Zugriff.",
    "Je hebt een vraag over deze factuur gesteld. Steffan neemt contact met je op; tot die tijd staan de herinneringen stil en hoef je niets te doen.": "Sie haben eine Frage zu dieser Rechnung gestellt. Steffan meldet sich bei Ihnen; bis dahin sind die Erinnerungen angehalten und Sie brauchen nichts zu tun.",
    "Je huidige voorkeuren konden niet worden geladen; hieronder staat de standaard.": "Ihre aktuellen Einstellungen konnten nicht geladen werden; unten steht der Standard.",
    "Je keuze geldt meteen voor dit portaal en wordt bewaard als jouw voorkeur bij CUSTOM+.": "Ihre Wahl gilt sofort für dieses Portal und wird als Ihre Einstellung bei CUSTOM+ gespeichert.",
    "Je kijkt mee als beheerder. In de voorvertoning kun je hier niets wijzigen; wat je aanpast wordt niet bewaard.": "Sie sehen als Administrator zu. In der Vorschau können Sie hier nichts ändern; was Sie anpassen, wird nicht gespeichert.",
    "Je kijkt naar de tijdlijn van het product dat nu open staat. Een ander product kies je via Producten.": "Sie sehen die Zeitleiste des aktuell geöffneten Produkts. Ein anderes Produkt wählen Sie über Produkte.",
    "Je laatste handelingen": "Ihre letzten Handlungen",
    "Je meldingen konden niet worden geladen.": "Ihre Mitteilungen konnten nicht geladen werden.",
    "Je vraag is verstuurd.": "Ihre Frage wurde gesendet.",
    "Je vraag komt in de Inbox van Steffan. Hij leest en beantwoordt elk bericht zelf, meestal binnen 1 werkdag.": "Ihre Frage landet im Posteingang von Steffan. Er liest und beantwortet jede Nachricht selbst, meist innerhalb von 1 Werktag.",
    "Je werkt in de demo. Alles wat je hier doet staat alleen in deze browser en verdwijnt zodra je de browsergegevens wist.": "Sie arbeiten in der Demo. Alles, was Sie hier tun, liegt nur in diesem Browser und verschwindet, sobald Sie die Browserdaten löschen.",
    "Je werkt in de demo. Alles wat je hier doet staat alleen in deze browser, in de browseropslag die het portaal en het beheer op dit apparaat delen. Het verdwijnt zodra je de browsergegevens wist en bereikt geen server.": "Sie arbeiten in der Demo. Alles, was Sie hier tun, liegt nur in diesem Browser, im Browserspeicher, den Portal und Verwaltung auf diesem Gerät teilen. Es verschwindet, sobald Sie die Browserdaten löschen, und erreicht keinen Server.",
