    "Van je mensen bewaart CUSTOM+ alleen wat jij invult: naam, functie, e-mailadres en de gekozen soorten mail.": "Von Ihrem Team speichert CUSTOM+ nur, was Sie eintragen: Name, Funktion, E-Mail-Adresse und die gewählten E-Mail-Arten.",
