    "Verdeling van je activiteit": "Verteilung Ihrer Aktivität",
    "Vernieuw de pagina of probeer het later opnieuw.": "Laden Sie die Seite neu oder versuchen Sie es später erneut.",
    "Verstuur": "Senden",
    "Vervallen op {datum}": "Fällig seit {datum}",
    "Vervalt op {datum}": "Fällig am {datum}",
    "Verwacht in de fase {fase}.": "Erwartet in der Phase {fase}.",
    "Verwijderen": "Löschen",
    "Vier onderdelen: je mensen, je meldingen, je taal en je gegevens. Bij je mensen en je meldingen staan wijzigingen pas vast als je ze opslaat; je krijgt een waarschuwing als je met onopgeslagen werk wegloopt.": "Vier Bereiche: Ihr Team, Ihre Mitteilungen, Ihre Sprache und Ihre Daten. Bei Ihrem Team und Ihren Mitteilungen gelten Änderungen erst, wenn Sie sie speichern; Sie werden gewarnt, wenn Sie mit ungespeicherter Arbeit weggehen.",
    "Voeg iemand toe die mee wil lezen — een collega van inkoop, marketing of ontwerp — en kies welke mail hij of zij krijgt.": "Fügen Sie jemanden hinzu, der mitlesen möchte — einen Kollegen aus Einkauf, Marketing oder Design — und wählen Sie, welche E-Mails er oder sie erhält.",
