    "Vraagt Steffan om een logo, artwork of specificatie, dan staat het hier met een uploadknop.": "Bittet Steffan um ein Logo, Artwork oder eine Spezifikation, steht es hier mit einer Upload-Schaltfläche.",
    "Vragen over je gegevens?": "Fragen zu Ihren Daten?",
    "Vul de datum van je betaling in.": "Geben Sie das Datum Ihrer Zahlung ein.",
    "Vul een bedrag in dat groter is dan nul.": "Geben Sie einen Betrag größer als null ein.",
    "Vul een naam in.": "Geben Sie einen Namen ein.",
    "Waar je gegevens staan": "Wo Ihre Daten liegen",
    "Waar je gegevens staan, hangt af van de omgeving waarin dit portaal draait; die kon nu niet worden vastgesteld.": "Wo Ihre Daten liegen, hängt von der Umgebung ab, in der dieses Portal läuft; die konnte gerade nicht ermittelt werden.",
    "Waar je gegevens staan, lees je onder Toegang en gegevens.": "Wo Ihre Daten liegen, lesen Sie unter Zugang und Daten.",
    "Wacht op jou": "Wartet auf Sie",
    "Wat er van je wordt bewaard, en waar": "Was über Sie gespeichert wird, und wo",
    "Wat er wordt vastgelegd: wanneer je een bestand bekijkt of downloadt, en elke handeling die je in dit portaal doet — een akkoord, een samplekeuze, een gemelde betaling, een bericht, een upload. Dat logboek lees je zelf onder Activiteit.": "Was festgehalten wird: wann Sie eine Datei ansehen oder herunterladen, und jede Handlung, die Sie in diesem Portal tun — eine Freigabe, eine Sample-Entscheidung, eine gemeldete Zahlung, eine Nachricht, ein Upload. Dieses Logbuch lesen Sie selbst unter Aktivität.",
    "Wat je keuze doet": "Was Ihre Wahl bewirkt",
    "Wat je mensen krijgen": "Was Ihr Team erhält",
    "Wat klopt er niet?": "Was stimmt nicht?",
