    "Wijzigingen teruggedraaid.": "Änderungen zurückgesetzt.",
    "Wil je iets laten aanpassen of verwijderen? Stuur Steffan een bericht; hij regelt het zelf.": "Möchten Sie etwas ändern oder löschen lassen? Schicken Sie Steffan eine Nachricht; er erledigt das selbst.",
    "Zet je een soort uit, dan stuurt CUSTOM+ die mails niet meer naar dit adres. In het portaal zie je alles nog gewoon.": "Schalten Sie eine Art aus, sendet CUSTOM+ diese E-Mails nicht mehr an diese Adresse. Im Portal sehen Sie weiterhin alles wie gewohnt.",
    "Zodra Steffan bestanden onder NNN met een fabriek deelt, staat hier welk bestand, welke fabriek en wanneer.": "Sobald Steffan Dateien unter NNN mit einer Fabrik teilt, steht hier, welche Datei, welche Fabrik und wann.",
    "Zodra er iets gebeurt — een update, een foto, een bericht, een betaling — verschijnt het hier.": "Sobald etwas passiert — ein Update, ein Foto, eine Nachricht, eine Zahlung — erscheint es hier.",
    "Zodra je hier een bestand opent of iets bevestigt, verschijnt het apparaat waarmee je dat deed.": "Sobald Sie hier eine Datei öffnen oder etwas bestätigen, erscheint das Gerät, mit dem Sie das getan haben.",
