    "Meestal binnen 1 werkdag antwoord": "Meist Antwort innerhalb von 1 Werktag",
    "Je vraag is verstuurd. Meestal antwoordt Steffan binnen 1 werkdag.": "Ihre Frage ist gesendet. Steffan antwortet meist innerhalb von 1 Werktag.",
    "Steffan neemt contact met je op over je vraag.": "Steffan meldet sich bei Ihnen wegen Ihrer Frage.",
    "Tot die tijd staan de herinneringen stil en hoef je niets te doen.": "Bis dahin sind die Erinnerungen angehalten und Sie müssen nichts tun.",
    "Bezwaar": "Widerspruch",
    "Scan de code met je bank-app: bedrag en kenmerk staan er al in.": "Scannen Sie den Code mit Ihrer Banking-App: Betrag und Verwendungszweck sind bereits enthalten.",
    "Liever handmatig? Neem dan bovenstaande gegevens over en vermeld het kenmerk.": "Lieber manuell? Übernehmen Sie dann die oben stehenden Angaben und geben Sie den Verwendungszweck an.",
    "Deze factuur staat niet in euro: maak over via SWIFT met bovenstaande gegevens en vermeld het kenmerk.": "Diese Rechnung lautet nicht auf Euro: Überweisen Sie per SWIFT mit den oben stehenden Angaben und geben Sie den Verwendungszweck an.",
    "Ik heb {bedrag} betaald": "Ich habe {bedrag} bezahlt",
    "Dit bedrag is hoger dan wat er openstaat ({open}).": "Dieser Betrag ist höher als der offene Betrag ({open}).",
    "Dankjewel. Steffan controleert het en je ziet hier Betaald zodra het klopt.": "Vielen Dank. Steffan prüft es, und Sie sehen hier Bezahlt, sobald es stimmt.",
    "Je vraag zet de herinneringen stil en legt de factuur bij Steffan.": "Ihre Frage hält die Erinnerungen an und legt die Rechnung bei Steffan ab.",
