    "{dag} {maand}": "{dag}. {maand}",
    "Nog geen activiteit; zodra er iets gebeurt, zie je het hier.": "Noch keine Aktivität; sobald etwas geschieht, sehen Sie es hier.",
    "Niets van deze soort in de tijdlijn.": "Nichts von dieser Art in der Zeitleiste.",
    "Alles wat jou aangaat in dit product: updates, foto’s, berichten, betalingen en zendingen.": "Alles, was Sie bei diesem Produkt betrifft: Updates, Fotos, Nachrichten, Zahlungen und Sendungen.",
    "Ook je eigen handelingen staan erin: een akkoord, een samplekeuze, een gemelde betaling, een download.": "Auch Ihre eigenen Handlungen stehen darin: eine Freigabe, eine Sample-Entscheidung, eine gemeldete Zahlung, ein Download.",
    "Interne notities van CUSTOM+ staan hier niet.": "Interne Notizen von CUSTOM+ stehen hier nicht.",
    "Je kijkt naar de tijdlijn van het product dat nu open staat.": "Sie sehen die Zeitleiste des Produkts, das gerade geöffnet ist.",
    "De mails van CUSTOM+ komen op dit adres.": "Die E-Mails von CUSTOM+ gehen an diese Adresse.",
    "Je bent de hoofdcontactpersoon van dit account; wat je precies krijgt, stel je in onder Meldingen.": "Sie sind der Hauptansprechpartner dieses Kontos; was genau Sie erhalten, stellen Sie unter Mitteilungen ein.",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase; alleen jij en CUSTOM+ kunnen erbij.": "Ihre Daten liegen in der Datenbank von CUSTOM+ bei Supabase; nur Sie und CUSTOM+ haben Zugriff.",
    "Elke rij is met toegangsregels beperkt tot je eigen klantaccount, via je login.": "Jede Zeile ist durch Zugriffsregeln auf Ihr eigenes Kundenkonto beschränkt, über Ihren Login.",
    "Je werkt in de demo: alles staat alleen in deze browser en bereikt geen server.": "Sie arbeiten in der Demo: Alles liegt nur in diesem Browser und erreicht keinen Server.",
    "Het portaal en het beheer delen op dit apparaat dezelfde browseropslag; alles verdwijnt zodra je de browsergegevens wist.": "Portal und Verwaltung teilen sich auf diesem Gerät denselben Browserspeicher; alles verschwindet, sobald Sie die Browserdaten löschen.",
    "Je mensen, je meldingen, je taal en je gegevens.": "Ihr Team, Ihre Mitteilungen, Ihre Sprache und Ihre Daten.",
    "Bij je mensen en je meldingen staan wijzigingen pas vast als je ze opslaat; loop je weg met onopgeslagen werk, dan krijg je een waarschuwing.": "Bei Ihrem Team und Ihren Mitteilungen gelten Änderungen erst, wenn Sie sie speichern; gehen Sie mit ungespeicherter Arbeit weg, erhalten Sie eine Warnung.",
    "Je kijkt mee als beheerder: in de voorvertoning wordt niets bewaard.": "Sie sehen als Administrator zu: In der Vorschau wird nichts gespeichert.",
    "Dit vinkje is een aanvraag: Steffan maakt de toegang aan en nodigt deze persoon per mail uit.": "Dieses Häkchen ist eine Anfrage: Steffan richtet den Zugang ein und lädt diese Person per E-Mail ein.",
    "De lijst met je mensen kon niet worden geladen; vernieuw de pagina.": "Die Liste Ihres Teams konnte nicht geladen werden; laden Sie die Seite neu.",
    "Per persoon kies je welke soorten mail iemand krijgt; jouw eigen mails regel je onder Meldingen.": "Je Person wählen Sie, welche E-Mail-Arten sie erhält; Ihre eigenen E-Mails regeln Sie unter Mitteilungen.",
    "Iemand zonder soorten krijgt geen mail; iedereen met een login ziet alles in dit portaal.": "Jemand ohne Arten erhält keine E-Mail; jeder mit einem Login sieht alles in diesem Portal.",
    "Je meldingen konden niet worden geladen; vernieuw de pagina.": "Ihre Mitteilungen konnten nicht geladen werden; laden Sie die Seite neu.",
    "De mails gaan naar het adres waarmee je inlogt.": "Die E-Mails gehen an die Adresse, mit der Sie sich anmelden.",
    "Zet je een soort uit, dan stuurt CUSTOM+ die mails niet meer; in het portaal zie je alles nog gewoon.": "Schalten Sie eine Art aus, sendet CUSTOM+ diese E-Mails nicht mehr; im Portal sehen Sie weiterhin alles.",
    "Welke mail je collega’s krijgen, regel je per persoon onder Jouw mensen.": "Welche E-Mails Ihre Kollegen erhalten, regeln Sie je Person unter Ihr Team.",
    "Je keuze geldt meteen voor dit portaal; je mails komen in het Nederlands of anders in het Engels.": "Ihre Wahl gilt sofort für dieses Portal; Ihre E-Mails kommen auf Niederländisch oder sonst auf Englisch.",
    "De keuze wordt bewaard als jouw voorkeur bij CUSTOM+.": "Die Wahl wird als Ihre Einstellung bei CUSTOM+ gespeichert.",
    "De mails van CUSTOM+ bestaan alleen in het Nederlands en het Engels; kies je een andere taal, dan komen je mails in het Engels.": "Die E-Mails von CUSTOM+ gibt es nur auf Niederländisch und Englisch; wählen Sie eine andere Sprache, kommen Ihre E-Mails auf Englisch.",
    "Het portaal legt geen inlogmoment vast; wat het wél vastlegt is een bestand bekijken of downloaden, een akkoord geven, een betaling melden.": "Das Portal hält keinen Login-Zeitpunkt fest; was es festhält, ist das Ansehen oder Herunterladen einer Datei, das Erteilen einer Freigabe, das Melden einer Zahlung.",
    "De apparaten waarmee je zelf iets deed in {product}; een aparte inlogregel is er niet.": "Die Geräte, mit denen Sie selbst etwas in {product} getan haben; einen eigenen Login-Eintrag gibt es nicht.",
    "De apparaten waarmee je zelf iets deed in je product; een aparte inlogregel is er niet.": "Die Geräte, mit denen Sie selbst etwas in Ihrem Produkt getan haben; einen eigenen Login-Eintrag gibt es nicht.",
    "Alles wat dit portaal over jou bewaart als één JSON-bestand, zonder de foto’s en PDF’s zelf.": "Alles, was dieses Portal über Sie speichert, als eine JSON-Datei, ohne die Fotos und PDFs selbst.",
    "Erin: producten en fases, foto’s en documenten, facturen, samples, berichten, zendingen, je mensen en je herbestellingen; zonder interne notities van CUSTOM+.": "Enthalten: Produkte und Phasen, Fotos und Dokumente, Rechnungen, Samples, Nachrichten, Sendungen, Ihr Team und Ihre Nachbestellungen; ohne interne Notizen von CUSTOM+.",
    "De bestanden zelf download je per stuk onder Bestanden.": "Die Dateien selbst laden Sie einzeln unter Dateien herunter.",
    "Wat er wordt vastgelegd: wanneer je een bestand bekijkt of downloadt, en elke handeling die je in dit portaal doet — een akkoord, een samplekeuze, een gemelde betaling, een bericht, een upload; dat logboek lees je zelf onder Activiteit.": "Was festgehalten wird: wann Sie eine Datei ansehen oder herunterladen, und jede Handlung, die Sie in diesem Portal ausführen — eine Freigabe, eine Sample-Entscheidung, eine gemeldete Zahlung, eine Nachricht, ein Upload; dieses Logbuch lesen Sie selbst unter Aktivität.",
    "Wil je iets laten aanpassen of verwijderen, stuur Steffan dan een bericht.": "Möchten Sie etwas ändern oder löschen lassen, senden Sie Steffan eine Nachricht.",
