    "Je idee wordt uitgewerkt tot een ontwerp dat echt te maken is; dit duurt meestal 1 tot 2 weken.": "Ihre Idee wird zu einem Design ausgearbeitet, das sich wirklich fertigen lässt; das dauert meist 1 bis 2 Wochen.",
    "Het ontwerp wordt doorgerekend voor de fabriek, zodat het zonder verrassingen te produceren is; dit duurt meestal 2 tot 4 weken.": "Das Design wird für die Fabrik durchgerechnet, damit es sich ohne Überraschungen produzieren lässt; das dauert meist 2 bis 4 Wochen.",
    "We kiezen en controleren de fabriek die bij je product past en leggen de afspraken vast; dit duurt meestal 2 tot 3 weken.": "Wir wählen und prüfen die Fabrik, die zu Ihrem Produkt passt, und halten die Vereinbarungen fest; das dauert meist 2 bis 3 Wochen.",
    "De mal wordt gemaakt en de eerste samples komen; dit duurt meestal 4 tot 10 weken.": "Das Werkzeug wird gebaut und die ersten Samples kommen; das dauert meist 4 bis 10 Wochen.",
    "De fabriek maakt je oplage en we controleren de kwaliteit tijdens de run; dit duurt meestal 4 tot 8 weken.": "Die Fabrik fertigt Ihre Auflage und wir prüfen die Qualität während des Laufs; das dauert meist 4 bis 8 Wochen.",
    "Je product wordt getest voor de regels van je markt en verscheept tot aan je deur; dit duurt meestal 3 tot 6 weken.": "Ihr Produkt wird für die Vorschriften Ihres Marktes getestet und bis an Ihre Tür verschifft; das dauert meist 3 bis 6 Wochen.",
