    /* FIXRONDE R0-5/R1-5 + R1-6: document zonder geüpload bestand en de
       route van het betaalpad naar het factuurdocument */
    "PDF volgt": "PDF à venir",
    "Het bestand wordt nog toegevoegd.": "Le fichier est encore en cours d’ajout.",
    "Nog geen bestand": "Pas encore de fichier",
    "Dit document is al aangemaakt, maar het bestand staat er nog niet bij. Zodra Steffan het toevoegt, verschijnt de download hier — opnieuw proberen helpt nu niet.": "Ce document existe déjà, mais le fichier n’y est pas encore. Dès que Steffan l’ajoute, le téléchargement apparaît ici — réessayer ne sert à rien pour l’instant.",
    "Bekijk het factuurdocument": "Voir le document de facture",
    "Zodra er een zending is, begint hier de reis": "Dès qu’il y aura une expédition, le voyage commencera ici",
    "Samples reizen per koerier, je productiebatch per zeevracht — elke zending krijgt hier zijn eigen reis met mijlpalen.": "Les échantillons voyagent par coursier, votre lot de production par fret maritime — chaque expédition a ici son propre voyage jalonné.",
    "Er is nu niets onderweg. Alles wat eerder is verzonden staat hieronder in het archief.": "Rien n’est en route actuellement. Tout ce qui a été expédié plus tôt se trouve ci-dessous dans les archives.",
    "Archief · {y} — geleverde zendingen blijven hier permanent staan": "Archives · {y} — les expéditions livrées restent ici en permanence",
    "Alles op één plek": "Tout au même endroit",
    "Contracten, offertes, facturen en rapporten, geordend per fase. Elke download wordt in het logboek genoteerd.": "Contrats, devis, factures et rapports, classés par phase. Chaque téléchargement est consigné dans le journal.",
    "Demo-omgeving": "Environnement de démonstration",
    "In de demo staat hier het echte bestand. In je eigen omgeving opent de download direct, via een beveiligde link die 15 minuten geldig is.": "Dans la démonstration, le vrai fichier se trouverait ici. Dans votre propre environnement, le téléchargement s’ouvre directement, via un lien sécurisé valable 15 minutes.",
    "Bestand niet beschikbaar in deze browser": "Fichier non disponible dans ce navigateur",
    "Dit bestand staat in de browseropslag van de computer waarop het is geüpload en reist niet mee naar andere browsers. Open het portaal daar, of mail steffan@customplus.nl.": "Ce fichier se trouve dans le stockage du navigateur de l’ordinateur où il a été téléversé et ne voyage pas vers d’autres navigateurs. Ouvrez le portail là-bas, ou écrivez à steffan@customplus.nl.",
    "Deze download is wel in je toegangslogboek genoteerd, zodat je ziet hoe dat werkt.": "Ce téléchargement a bien été consigné dans votre journal d’accès, pour que vous voyiez comment cela fonctionne.",
    "Het bestand kon nu niet worden opgehaald. Probeer het over een minuut opnieuw of mail steffan@customplus.nl.": "Le fichier n’a pas pu être récupéré. Réessayez dans une minute ou écrivez à steffan@customplus.nl.",
    "Zodra Steffan het eerste document deelt — meestal de NNN overeenkomst — staat het hier, geordend per fase en permanent bewaard.": "Dès que Steffan partagera le premier document — généralement l’accord NNN — il figurera ici, classé par phase et conservé en permanence.",
    "Wordt verwacht in deze fase": "Attendu dans cette phase",
    "Verschijnt hier zodra Steffan het deelt.": "Il apparaîtra ici dès que Steffan le partagera.",
