    "Je keurt elke fase goed vóór je betaalt. Hieronder staat wat is betaald, wat openstaat en wat er nog volgt — elk bedrag komt van een echte factuur.": "Vous validez chaque phase avant de payer. Ci-dessous : ce qui est payé, ce qui est en attente et ce qui reste à venir — chaque montant provient d’une vraie facture.",
