    "Scan met je bank-app": "Scannez avec votre application bancaire",
    "Scan de code met je bank-app: bedrag en kenmerk staan er al in. Liever handmatig? Neem dan bovenstaande gegevens over en vermeld het kenmerk.": "Scannez le code avec votre application bancaire : le montant et la référence y figurent déjà. Vous préférez le faire manuellement ? Reprenez les données ci-dessus et indiquez la référence.",
    "Vermeld het kenmerk bij je overboeking — daarmee wordt je betaling meteen aan deze factuur gekoppeld.": "Indiquez la référence lors de votre virement — votre paiement sera ainsi immédiatement rattaché à cette facture.",
    "Deze factuur staat niet in euro. Maak over via SWIFT met bovenstaande gegevens en vermeld het kenmerk.": "Cette facture n'est pas libellée en euros. Effectuez un virement SWIFT avec les données ci-dessus et indiquez la référence.",
    "Vermeld bij de overboeking het kenmerk {n} — daarmee wordt je betaling meteen aan deze factuur gekoppeld.": "Indiquez la référence {n} lors du virement — votre paiement sera ainsi immédiatement rattaché à cette facture.",
    "Vermeld bij de overboeking het kenmerk {n}. Deze factuur staat niet in euro; maak over via SWIFT met bovenstaande gegevens.": "Indiquez la référence {n} lors du virement. Cette facture n'est pas libellée en euros ; effectuez un virement SWIFT avec les données ci-dessus.",
