    "en wanneer": "et quand",
    "Jouw bestanden zijn van jou. Dit logboek laat zien wat ermee is gebeurd.": "Vos fichiers vous appartiennent. Ce journal montre ce qu’il en a été fait.",
    "Dit logboek toont elke keer dat een bestand van dit project is bekeken, gedownload of gedeeld.": "Ce journal montre chaque consultation, téléchargement ou partage d’un fichier de ce projet.",
