    "Nog geen activiteit.": "Pas encore d’activité.",
    "Je bent helemaal bij.": "Vous êtes à jour.",
    "Nieuwe foto: {x}": "Nouvelle photo : {x}",
    "update uit de fabriek": "mise à jour de l’usine",
    "FASE {n}": "PHASE {n}",
    "ANTWOORD": "RÉPONSE",
    "Steffan beantwoordde je vraag: ‘{x}’": "Steffan a répondu à votre question : ‘{x}’",
    "Nieuw document: {x}": "Nouveau document : {x}",
    "FACTUUR": "FACTURE",
    "Factuur betaald: {x}": "Facture payée : {x}",
    "Er staat een factuur voor je klaar: {x}": "Une facture vous attend : {x}",
    "Zending: {x}": "Expédition : {x}",
    "goedgekeurd": "validé",
    "Uitleg: {term}": "Explication : {term}",
    "Lees meer op de site": "En lire plus sur le site",
    "De statistische norm die bepaalt hoeveel afwijkingen een steekproef mag bevatten voordat de hele batch wordt afgekeurd. Elke inspectie in je portaal wordt tegen deze norm gemeten.": "La norme statistique qui détermine combien de défauts un échantillon peut contenir avant que tout le lot soit refusé. Chaque inspection de votre portail est mesurée à l’aune de cette norme.",
    "Een contract dat is opgesteld om afdwingbaar te zijn bij Chinese rechtbanken, getekend vóór er één bestand de deur uit gaat. Een westerse NDA alleen is dat in de praktijk vaak niet.": "Un contrat rédigé pour être opposable devant les tribunaux chinois, signé avant qu’un seul fichier ne sorte. Un simple NDA occidental ne l’est souvent pas en pratique.",
    "De stap waarin je ontwerp wordt getoetst aan het productieproces dat het echt gaat maken, vóór er tooling wordt besteld. Een mooi CAD bestand en een maakbaar onderdeel zijn niet hetzelfde.": "L’étape où votre design est confronté au procédé de production qui le fabriquera réellement, avant de commander l’outillage. Un beau fichier CAD et une pièce fabricable, ce n’est pas la même chose.",
    "De kleinste oplage die een fabriek wil draaien. Voor spuitgietwerk ligt die doorgaans hoger dan voor CNC of plaatwerk, omdat de mal moet worden terugverdiend.": "La plus petite série qu’une usine accepte de produire. En injection plastique, elle est généralement plus élevée qu’en CNC ou en tôlerie, car le moule doit être amorti.",
    "De controle van binnenkomend materiaal vóórdat de productie start, zodat een afwijking in de grondstof nooit een hele run kan raken.": "Le contrôle de la matière entrante avant le démarrage de la production, pour qu’un défaut de matière première ne puisse jamais toucher toute une série.",
    "Controles tijdens de productierun zelf, niet pas aan het einde — zo wordt een afwijking gevonden terwijl die nog goedkoop te herstellen is.": "Des contrôles pendant la production elle-même, pas seulement à la fin — un défaut est ainsi détecté tant qu’il est encore peu coûteux à corriger.",
    "De eindcontrole op de afgeronde batch, vlak vóór verzending, gemeten tegen hetzelfde golden sample waarmee de run begon.": "Le contrôle final du lot terminé, juste avant l’expédition, mesuré par rapport au même golden sample qu’au début de la série.",
    "Het allereerste schot uit een nieuwe mal. Een T0 is zelden meteen goed — deze ronde laat zien wat er aan de mal moet worden bijgesteld.": "Le tout premier tir d’un moule neuf. Un T0 est rarement bon du premier coup — ce tour montre ce qu’il faut ajuster sur le moule.",
    "De sampleronde na de eerste bijstelling van de mal. Elke volgende ronde brengt het sample dichter bij het exemplaar dat jij goedkeurt.": "Le tour d’échantillonnage après le premier ajustement du moule. Chaque tour suivant rapproche l’échantillon de l’exemplaire que vous validez.",
    "De ronde na de tweede bijstelling, vaak de laatste verfijning zoals polijstwerk aan de mal. Keur jij deze goed, dan wordt dit exemplaar meestal het golden sample.": "Le tour après le deuxième ajustement, souvent l’ultime finition comme le polissage du moule. Si vous le validez, cet exemplaire devient généralement le golden sample.",
    "Het sample dat jij goedkeurt als dé standaard. Elke inspectie tijdens de productie meet de batch tegen precies dit exemplaar — niet tegen een gevoel.": "L’échantillon que vous validez comme référence absolue. Chaque inspection pendant la production mesure le lot par rapport à cet exemplaire précis — pas à une impression.",
    "Het officiële vervoersdocument van een zeevracht: het bewijs dat de lading aan boord is én het document waarmee de container op de bestemming wordt vrijgegeven.": "Le document de transport officiel d’un fret maritime : la preuve que la cargaison est à bord et le document qui libère le conteneur à destination.",
    /* factuurmodule fase 5 — de herinneringsteksten */
    "Herinnering: factuur {nummer} vervalt {vervaldatum}": "Rappel : la facture {nummer} arrive à échéance le {vervaldatum}",
    "Beste {naam},\n\nEen vriendelijke herinnering: factuur {nummer} van {bedrag} vervalt op {vervaldatum}.\n\nIs de betaling al onderweg, dan kun je dit bericht als niet verzonden beschouwen.\n\nMet vriendelijke groet,\n{afzender}": "Bonjour {naam},\n\nUn rappel amical : la facture {nummer} d’un montant de {bedrag} arrive à échéance le {vervaldatum}.\n\nSi le paiement est déjà en route, merci de ne pas tenir compte de ce message.\n\nCordialement,\n{afzender}",
    "Factuur {nummer} staat nog open": "La facture {nummer} est toujours impayée",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} is op {vervaldatum} vervallen en staat nog open. Waarschijnlijk is het je ontgaan.\n\nHet openstaande bedrag is {openstaand}. Klopt er iets niet, laat het dan weten — dan lossen we het samen op.\n\nMet vriendelijke groet,\n{afzender}": "Bonjour {naam},\n\nLa facture {nummer} d’un montant de {bedrag} est échue depuis le {vervaldatum} et reste impayée. Elle vous a sans doute échappé.\n\nLe montant restant dû est de {openstaand}. Si quelque chose ne va pas, dites-le-nous et nous le réglerons ensemble.\n\nCordialement,\n{afzender}",
    "Tweede herinnering: factuur {nummer}": "Deuxième rappel : facture {nummer}",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} staat sinds {vervaldatum} open. Het openstaande bedrag is {openstaand}.\n\nWe hebben nog geen betaling ontvangen en ook geen bericht. Wil je de betaling deze week in orde maken, of laten weten waar het aan ligt?\n\nMet vriendelijke groet,\n{afzender}": "Bonjour {naam},\n\nLa facture {nummer} d’un montant de {bedrag} est impayée depuis le {vervaldatum}. Le montant restant dû est de {openstaand}.\n\nNous n’avons reçu ni paiement ni message. Pouvez-vous effectuer le paiement cette semaine ou nous indiquer ce qui le retarde ?\n\nCordialement,\n{afzender}",
    "Laatste aanmaning: factuur {nummer}": "Dernière mise en demeure : facture {nummer}",
    "Beste {naam},\n\nOndanks eerdere herinneringen staat factuur {nummer} nog open. Het openstaande bedrag is {openstaand}, vervallen op {vervaldatum}.\n\nDit is de laatste aanmaning. Zonder betaling of bericht binnen veertien dagen dragen we de vordering over.\n\nMet vriendelijke groet,\n{afzender}": "Bonjour {naam},\n\nMalgré nos rappels précédents, la facture {nummer} reste impayée. Le montant restant dû est de {openstaand}, échu depuis le {vervaldatum}.\n\nCeci est la dernière mise en demeure. Sans paiement ni message sous quatorze jours, nous transmettrons la créance.\n\nCordialement,\n{afzender}",
    "Over factuur {nummer}": "Au sujet de la facture {nummer}",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} staat nog open; het openstaande bedrag is {openstaand}.\n\nMet vriendelijke groet,\n{afzender}": "Bonjour {naam},\n\nLa facture {nummer} d’un montant de {bedrag} est toujours impayée ; le montant restant dû est de {openstaand}.\n\nCordialement,\n{afzender}",
    "Rente over de te late betaling": "Intérêts de retard de paiement",
    "Buitengerechtelijke incassokosten": "Frais de recouvrement extrajudiciaires",
