    "Vraag of betaalprobleem melden": "Signaler une question ou un problème de paiement",
    "Stel je vraag, of laat weten waar de betaling vastloopt. Je bericht komt binnen bij Steffan zelf, op dezelfde plek als je andere projectvragen. Je hoort meestal binnen 1 werkdag iets.": "Posez votre question ou dites-nous où le paiement bloque. Votre message arrive directement chez Steffan, au même endroit que vos autres questions de projet. Vous avez généralement une réponse sous 1 jour ouvré.",
    "Je bericht": "Votre message",
    "Vul eerst een bericht in.": "Merci d’écrire d’abord un message.",
    "Bedankt — je bericht is binnengekomen. Je hoort meestal binnen 1 werkdag iets.": "Merci — votre message est bien arrivé. Vous avez généralement une réponse sous 1 jour ouvré.",
    "Je bericht kon niet worden verstuurd. Probeer het zo nog eens, of mail steffan@customplus.nl.": "Votre message n’a pas pu être envoyé. Réessayez dans un instant ou écrivez à steffan@customplus.nl.",
    "Deze pagina hoort bij één factuur en is alleen voor jou bedoeld. Deel de link niet — wie hem heeft, kan deze factuur bekijken.": "Cette page concerne une seule facture et vous est destinée. Ne partagez pas le lien — toute personne qui l’a peut consulter cette facture.",
    /* klantportaal 2026-09 — hoofdstuk: schermen, acties, foutzinnen */
    "1 contactpersoon": "1 contact",
    "1 gebeurtenis": "1 événement",
    "1 gesprek wacht op je": "1 conversation vous attend",
    "1 open factuur": "1 facture en attente",
    "Aangeleverd door jou": "Fourni par vous",
    "Aangemaakt op {datum}": "Créé le {datum}",
    "Activiteit": "Activité",
    "Al overgemaakt? Meld het hier. Een melding is geen boeking: Steffan controleert je betaling en zet de factuur daarna op betaald.": "Déjà viré ? Signalez-le ici. Un signalement n’est pas une comptabilisation : Steffan vérifie votre paiement, puis passe la facture en payée.",
    "Alle {n} foto’s": "Les {n} photos",
    "Alles is betaald.": "Tout est payé.",
    "Alles wat dit portaal over jou en je producten bewaart, als één JSON-bestand: producten en fases, foto’s en documenten, facturen, samples, berichten, zendingen, je mensen en je herbestellingen. Zonder interne notities van CUSTOM+.": "Tout ce que ce portail conserve sur vous et vos produits, en un seul fichier JSON : produits et phases, photos et documents, factures, samples, messages, expéditions, vos collaborateurs et vos réassorts. Sans les notes internes de CUSTOM+.",
    "Alles wat jou aangaat in dit product: updates van Steffan, je eigen handelingen, foto’s, berichten, betalingen en zendingen. Interne notities van CUSTOM+ staan hier niet.": "Tout ce qui vous concerne dans ce produit : mises à jour de Steffan, vos propres actions, photos, messages, paiements et expéditions. Les notes internes de CUSTOM+ n’y figurent pas.",
    "Annuleer": "Annuler",
    "Apparaten waarmee je dit portaal gebruikte": "Appareils avec lesquels vous avez utilisé ce portail",
