    "Betalingen": "Paiements",
    "Bewerken": "Modifier",
    "Bezig met opslaan…": "Enregistrement…",
    "Bijvoorbeeld: dit bedrag zat volgens de offerte al in de toolingprijs.": "Par exemple : selon le devis, ce montant était déjà compris dans le prix de l’outillage.",
    "Bijvoorbeeld: dit is de definitieve versie.": "Par exemple : ceci est la version définitive.",
