    "Creditnota {nummer}": "Avoir {nummer}",
    "Creditnota’s": "Avoirs",
    "Datum van je betaling": "Date de votre paiement",
    "De bestanden zelf — de foto’s en PDF’s — zitten er niet in; die download je per stuk onder Bestanden.": "Les fichiers eux-mêmes — les photos et les PDF — n’y sont pas ; vous les téléchargez un par un sous Fichiers.",
    "De lijst met je mensen kon niet worden geladen.": "La liste de vos collaborateurs n’a pas pu être chargée.",
    "De mails van CUSTOM+ bestaan in het Nederlands en het Engels. Kies je een andere taal, dan komen je mails in het Engels.": "Les e-mails de CUSTOM+ existent en néerlandais et en anglais. Si vous choisissez une autre langue, vos e-mails arriveront en anglais.",
    "Demo: alles staat in deze browser": "Démo : tout est stocké dans ce navigateur",
    "Dit bestand is groter dan 25 MB. Kies een kleiner bestand.": "Ce fichier dépasse 25 Mo. Choisissez un fichier plus petit.",
    "Dit e-mailadres ziet er niet goed uit.": "Cette adresse e-mail ne semble pas correcte.",
    "Dit is een aanvraag: Steffan maakt de toegang aan en nodigt deze persoon per mail uit. Het vinkje zelf geeft nog geen login.": "Ceci est une demande : Steffan crée l’accès et invite cette personne par e-mail. La case cochée ne donne pas encore d’identifiant.",
    "Dit is een demo-account.": "Ceci est un compte de démonstration.",
    "Dit onderdeel kon niet worden geladen.": "Cette section n’a pas pu être chargée.",
    "Dit onderdeel van Instellingen bestaat niet.": "Cette section des Paramètres n’existe pas.",
    "Dit onderdeel wordt nog gebouwd.": "Cette section est encore en construction.",
    "Dit onderdeel wordt nog gebouwd. Je taal kies je in het gebruikersmenu rechtsboven; daar staat ook Download alles.": "Cette section est encore en construction. Vous choisissez votre langue dans le menu utilisateur en haut à droite ; Tout télécharger s’y trouve aussi.",
    "Dit overzicht hoort bij het product dat nu open staat; wissel van product om een ander logboek te zien.": "Cet aperçu concerne le produit actuellement ouvert ; changez de produit pour voir un autre journal.",
    "Dit product kon niet worden gevonden.": "Ce produit est introuvable.",
    "Dit zijn jouw eigen mails. Welke mail je collega’s krijgen, regel je per persoon onder Jouw mensen.": "Ce sont vos propres e-mails. Les e-mails que reçoivent vos collègues se règlent par personne sous Vos collaborateurs.",
    "Download alles": "Tout télécharger",
    "Download alles geeft je een bestand met alles wat je in het portaal ziet: producten, documenten, facturen en gesprekken, zonder interne velden.": "Tout télécharger vous donne un fichier avec tout ce que vous voyez dans le portail : produits, documents, factures et conversations, sans les champs internes.",
    "Downloaden is hier nog niet beschikbaar.": "Le téléchargement n’est pas encore disponible ici.",
    "Een creditnota vermindert wat je nog moet betalen. Het bedrag is al verrekend in de stand van de bijbehorende factuur.": "Un avoir réduit ce que vous devez encore payer. Le montant est déjà déduit du solde de la facture correspondante.",
    "Elk bestandstype kan, tot {mb} MB — bijvoorbeeld PDF, JPG, PNG, AI of ZIP.": "Tout type de fichier convient, jusqu’à {mb} Mo — par exemple PDF, JPG, PNG, AI ou ZIP.",
    "Elke factuur die Steffan publiceert, staat hier met haar stand, vervaldatum en betaalgegevens.": "Chaque facture publiée par Steffan figure ici avec son état, sa date d’échéance et ses informations de paiement.",
    "Er is wel activiteit van andere soorten. Kies “Alles” om de volledige tijdlijn te zien.": "Il y a de l’activité d’autres types. Choisissez « Tout » pour voir la chronologie complète.",
    "Er staat niets open.": "Rien n’est en attente.",
    "Er staat nog geen product open": "Aucun produit n’est encore ouvert",
    "Er wacht 1 bericht op jouw reactie.": "1 message attend votre réponse.",
    "Er wachten {n} berichten op jouw reactie.": "{n} messages attendent votre réponse.",
    "Factuur gesloten": "Facture repliée",
    "Foto: {bijschrift}. {herkomst}. Opent het product.": "Photo : {bijschrift}. {herkomst}. Ouvre le produit.",
