    "Gesprekken": "Conversations",
    "Gesteld op {datum}": "Posée le {datum}",
    "Gevraagd op {datum}": "Demandé le {datum}",
    "Herstel": "Rétablir",
    "Het adres wijst naar iets wat het portaal niet kent.": "L’adresse renvoie à quelque chose que le portail ne connaît pas.",
    "Het factuurnummer, of de omschrijving die je bij je bank hebt gebruikt.": "Le numéro de facture, ou le libellé que vous avez utilisé auprès de votre banque.",
    "Het hoort niet bij jouw account, of het bestaat niet meer.": "Cela n’appartient pas à votre compte, ou n’existe plus.",
    "Het portaal legt geen aparte inlogregel vast. Dit zijn de apparaten waarmee je iets deed in je product: een bestand bekeken of gedownload, een akkoord gegeven, een betaling gemeld.": "Le portail n’enregistre pas de ligne de connexion distincte. Ce sont les appareils avec lesquels vous avez agi dans votre produit : consulté ou téléchargé un fichier, donné une validation, signalé un paiement.",
    "Hoofdcontactpersoon — logt in en ontvangt de mails die je onder Meldingen aanzet.": "Contact principal — se connecte et reçoit les e-mails que vous activez sous Notifications.",
    "In de voorvertoning wisselt alleen dit scherm van taal; de voorkeur van de klant blijft staan.": "Dans l’aperçu, seul cet écran change de langue ; la préférence du client reste inchangée.",
    "In {valuta}, bijvoorbeeld 1234,56": "En {valuta}, par exemple 1234,56",
    "Ingelogd als hoofdcontactpersoon van dit account.": "Connecté en tant que contact principal de ce compte.",
    "Instellingen": "Paramètres",
    "Ja, verwijderen": "Oui, supprimer",
    "Je bent de hoofdcontactpersoon van dit account. De mails van CUSTOM+ komen op dit adres; wat je precies krijgt, stel je in onder Meldingen.": "Vous êtes le contact principal de ce compte. Les e-mails de CUSTOM+ arrivent à cette adresse ; ce que vous recevez exactement se règle sous Notifications.",
    "Je bericht komt in de Inbox van Steffan. Hij reageert meestal binnen 1 werkdag.": "Votre message arrive dans la boîte de réception de Steffan. Il répond généralement sous 1 jour ouvré.",
    "Je betaling is gemeld.": "Votre paiement a été signalé.",
    "Je dossier wordt gedownload als JSON-bestand.": "Votre dossier est téléchargé sous forme de fichier JSON.",
    "Je dossier wordt samengesteld…": "Votre dossier est en cours de préparation…",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase. Alleen jij, via je login, en CUSTOM+ kunnen erbij.": "Vos données se trouvent dans la base de données de CUSTOM+ chez Supabase. Seuls vous, via votre identifiant, et CUSTOM+ y avez accès.",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase. Elke rij is met toegangsregels beperkt tot je eigen klantaccount: alleen jij, via je login, en CUSTOM+ kunnen erbij.": "Vos données se trouvent dans la base de données de CUSTOM+ chez Supabase. Chaque ligne est limitée par des règles d’accès à votre propre compte client : seuls vous, via votre identifiant, et CUSTOM+ y avez accès.",
    "Je hebt een vraag over deze factuur gesteld. Steffan neemt contact met je op; tot die tijd staan de herinneringen stil en hoef je niets te doen.": "Vous avez posé une question sur cette facture. Steffan vous contactera ; d’ici là, les rappels sont suspendus et vous n’avez rien à faire.",
    "Je huidige voorkeuren konden niet worden geladen; hieronder staat de standaard.": "Vos préférences actuelles n’ont pas pu être chargées ; ci-dessous figure le réglage par défaut.",
    "Je keuze geldt meteen voor dit portaal en wordt bewaard als jouw voorkeur bij CUSTOM+.": "Votre choix s’applique immédiatement à ce portail et est enregistré comme votre préférence chez CUSTOM+.",
    "Je kijkt mee als beheerder. In de voorvertoning kun je hier niets wijzigen; wat je aanpast wordt niet bewaard.": "Vous consultez en tant qu’administrateur. Dans l’aperçu, vous ne pouvez rien modifier ici ; ce que vous ajustez n’est pas enregistré.",
    "Je kijkt naar de tijdlijn van het product dat nu open staat. Een ander product kies je via Producten.": "Vous voyez la chronologie du produit actuellement ouvert. Vous choisissez un autre produit via Produits.",
    "Je laatste handelingen": "Vos dernières actions",
    "Je meldingen konden niet worden geladen.": "Vos notifications n’ont pas pu être chargées.",
    "Je vraag is verstuurd.": "Votre question a été envoyée.",
    "Je vraag komt in de Inbox van Steffan. Hij leest en beantwoordt elk bericht zelf, meestal binnen 1 werkdag.": "Votre question arrive dans la boîte de réception de Steffan. Il lit et répond lui-même à chaque message, généralement sous 1 jour ouvré.",
    "Je werkt in de demo. Alles wat je hier doet staat alleen in deze browser en verdwijnt zodra je de browsergegevens wist.": "Vous travaillez dans la démo. Tout ce que vous faites ici n’est stocké que dans ce navigateur et disparaît dès que vous effacez les données du navigateur.",
    "Je werkt in de demo. Alles wat je hier doet staat alleen in deze browser, in de browseropslag die het portaal en het beheer op dit apparaat delen. Het verdwijnt zodra je de browsergegevens wist en bereikt geen server.": "Vous travaillez dans la démo. Tout ce que vous faites ici n’est stocké que dans ce navigateur, dans le stockage que le portail et l’administration partagent sur cet appareil. Cela disparaît dès que vous effacez les données du navigateur et n’atteint aucun serveur.",
    "Jouw account": "Votre compte",
    "Jouw bericht": "Votre message",
    "Jouw eigen meldingen staan onder Meldingen, niet in deze lijst.": "Vos propres notifications se trouvent sous Notifications, pas dans cette liste.",
