    "Kies eerst een product.": "Choisissez d’abord un produit.",
    "Kies eerst een product; daarna zie je hier alles wat er in dat product gebeurde.": "Choisissez d’abord un produit ; vous verrez ensuite ici tout ce qui s’est passé dans ce produit.",
    "Klaar": "Terminé",
    "Klopt er iets niet? Beschrijf het hier. Je vraag zet de herinneringen stil en legt de factuur bij Steffan tot jullie het hebben opgelost.": "Quelque chose ne va pas ? Décrivez-le ici. Votre question suspend les rappels et confie la facture à Steffan jusqu’à ce que vous ayez réglé la question ensemble.",
