    "Over welk product gaat je vraag?": "Sur quel produit porte votre question ?",
    "Per persoon kies je soorten mail. Iemand zonder soorten krijgt niets; iedereen met een login ziet alles in dit portaal.": "Vous choisissez les types d’e-mail par personne. Une personne sans type ne reçoit rien ; toute personne avec un identifiant voit tout dans ce portail.",
