    "Stel hier je eerste vraag. Steffan leest en beantwoordt elk bericht zelf.": "Posez ici votre première question. Steffan lit et répond lui-même à chaque message.",
    "Taal kiezen is hier nog niet beschikbaar; gebruik de taalknoppen bovenaan.": "Le choix de la langue n’est pas encore disponible ici ; utilisez les boutons de langue en haut.",
    "Taal opgeslagen.": "Langue enregistrée.",
    "Terug naar Instellingen": "Retour aux Paramètres",
    "Terug naar de lijst": "Retour à la liste",
    "Tijdlijn, 1 gebeurtenis": "Chronologie, 1 événement",
