    "Toegang en download": "Accès et téléchargement",
    "Toevoegen aan de lijst": "Ajouter à la liste",
    "Toevoegen en wijzigen is hier nog niet beschikbaar.": "L’ajout et la modification ne sont pas encore disponibles ici.",
    "Toon alle foto’s ({n})": "Afficher toutes les photos ({n})",
    "Toon alles": "Tout afficher",
    "Totaal": "Total",
    "Type: {type}": "Type : {type}",
    "Van deze regel is alleen de dag vastgelegd, niet het tijdstip.": "Pour cette ligne, seul le jour a été enregistré, pas l’heure.",
    "Van je mensen bewaart CUSTOM+ alleen wat jij invult: naam, functie, e-mailadres en de gekozen soorten mail.": "De vos collaborateurs, CUSTOM+ ne conserve que ce que vous saisissez : nom, fonction, adresse e-mail et les types d’e-mail choisis.",
    "Van jou": "De vous",
    "Verdeling van je activiteit": "Répartition de votre activité",
    "Vernieuw de pagina of probeer het later opnieuw.": "Actualisez la page ou réessayez plus tard.",
    "Verstuur": "Envoyer",
    "Vervallen op {datum}": "Échue le {datum}",
    "Vervalt op {datum}": "Échéance le {datum}",
    "Verwacht in de fase {fase}.": "Attendu dans la phase {fase}.",
    "Verwijderen": "Supprimer",
    "Vier onderdelen: je mensen, je meldingen, je taal en je gegevens. Bij je mensen en je meldingen staan wijzigingen pas vast als je ze opslaat; je krijgt een waarschuwing als je met onopgeslagen werk wegloopt.": "Quatre sections : vos collaborateurs, vos notifications, votre langue et vos données. Pour vos collaborateurs et vos notifications, les modifications ne sont définitives qu’une fois enregistrées ; vous êtes averti si vous quittez avec du travail non enregistré.",
    "Voeg iemand toe die mee wil lezen — een collega van inkoop, marketing of ontwerp — en kies welke mail hij of zij krijgt.": "Ajoutez une personne qui souhaite suivre — un collègue des achats, du marketing ou du design — et choisissez les e-mails qu’elle reçoit.",
    "Volgende betaling": "Prochain paiement",
    "Vraag over deze factuur": "Question sur cette facture",
    "Vraagt Steffan om een logo, artwork of specificatie, dan staat het hier met een uploadknop.": "Si Steffan demande un logo, un artwork ou une spécification, cela apparaît ici avec un bouton d’envoi.",
    "Vragen over je gegevens?": "Des questions sur vos données ?",
    "Vul de datum van je betaling in.": "Saisissez la date de votre paiement.",
    "Vul een bedrag in dat groter is dan nul.": "Saisissez un montant supérieur à zéro.",
    "Vul een naam in.": "Saisissez un nom.",
    "Waar je gegevens staan": "Où se trouvent vos données",
    "Waar je gegevens staan, hangt af van de omgeving waarin dit portaal draait; die kon nu niet worden vastgesteld.": "L’emplacement de vos données dépend de l’environnement dans lequel ce portail fonctionne ; il n’a pas pu être déterminé pour le moment.",
    "Waar je gegevens staan, lees je onder Toegang en gegevens.": "Où se trouvent vos données, vous le lisez sous Accès et données.",
    "Wacht op jou": "Vous attend",
    "Wat er van je wordt bewaard, en waar": "Ce qui est conservé sur vous, et où",
    "Wat er wordt vastgelegd: wanneer je een bestand bekijkt of downloadt, en elke handeling die je in dit portaal doet — een akkoord, een samplekeuze, een gemelde betaling, een bericht, een upload. Dat logboek lees je zelf onder Activiteit.": "Ce qui est enregistré : quand vous consultez ou téléchargez un fichier, et chaque action que vous faites dans ce portail — une validation, un choix de sample, un paiement signalé, un message, un envoi de fichier. Vous lisez ce journal vous-même sous Activité.",
    "Wat je keuze doet": "Ce que fait votre choix",
    "Wat je mensen krijgen": "Ce que reçoivent vos collaborateurs",
    "Wat klopt er niet?": "Qu’est-ce qui ne va pas ?",
    "Wat we van jou nodig hebben": "Ce dont nous avons besoin de votre part",
    "Welke mail krijgt deze persoon?": "Quels e-mails cette personne reçoit-elle ?",
    "Wie krijgt wat": "Qui reçoit quoi",
    "Wijzigingen opgeslagen.": "Modifications enregistrées.",
    "Wijzigingen opslaan": "Enregistrer les modifications",
    "Wijzigingen teruggedraaid.": "Modifications annulées.",
    "Wil je iets laten aanpassen of verwijderen? Stuur Steffan een bericht; hij regelt het zelf.": "Vous voulez faire modifier ou supprimer quelque chose ? Envoyez un message à Steffan ; il s’en occupe lui-même.",
    "Zet je een soort uit, dan stuurt CUSTOM+ die mails niet meer naar dit adres. In het portaal zie je alles nog gewoon.": "Si vous désactivez un type, CUSTOM+ n’envoie plus ces e-mails à cette adresse. Dans le portail, vous voyez toujours tout normalement.",
