    "Je gegevens staan in de database van CUSTOM+ bij Supabase; alleen jij en CUSTOM+ kunnen erbij.": "Vos données se trouvent dans la base de données de CUSTOM+ chez Supabase ; seuls vous et CUSTOM+ y avez accès.",
    "Elke rij is met toegangsregels beperkt tot je eigen klantaccount, via je login.": "Chaque ligne est limitée par des règles d’accès à votre propre compte client, via votre identifiant.",
    "Je werkt in de demo: alles staat alleen in deze browser en bereikt geen server.": "Vous travaillez dans la démo : tout n’est stocké que dans ce navigateur et n’atteint aucun serveur.",
    "Het portaal en het beheer delen op dit apparaat dezelfde browseropslag; alles verdwijnt zodra je de browsergegevens wist.": "Le portail et l’administration partagent le même stockage de navigateur sur cet appareil ; tout disparaît dès que vous effacez les données du navigateur.",
    "Je mensen, je meldingen, je taal en je gegevens.": "Vos collaborateurs, vos notifications, votre langue et vos données.",
    "Bij je mensen en je meldingen staan wijzigingen pas vast als je ze opslaat; loop je weg met onopgeslagen werk, dan krijg je een waarschuwing.": "Pour vos collaborateurs et vos notifications, les modifications ne sont définitives qu’une fois enregistrées ; si vous quittez avec du travail non enregistré, vous recevez un avertissement.",
    "Je kijkt mee als beheerder: in de voorvertoning wordt niets bewaard.": "Vous consultez en tant qu’administrateur : rien n’est enregistré dans l’aperçu.",
    "Dit vinkje is een aanvraag: Steffan maakt de toegang aan en nodigt deze persoon per mail uit.": "Cette case est une demande : Steffan crée l’accès et invite cette personne par e-mail.",
    "De lijst met je mensen kon niet worden geladen; vernieuw de pagina.": "La liste de vos collaborateurs n’a pas pu être chargée ; actualisez la page.",
    "Per persoon kies je welke soorten mail iemand krijgt; jouw eigen mails regel je onder Meldingen.": "Pour chaque personne, vous choisissez les types d’e-mail qu’elle reçoit ; vos propres e-mails se règlent sous Notifications.",
    "Iemand zonder soorten krijgt geen mail; iedereen met een login ziet alles in dit portaal.": "Une personne sans aucun type ne reçoit pas d’e-mail ; toute personne avec un identifiant voit tout dans ce portail.",
    "Je meldingen konden niet worden geladen; vernieuw de pagina.": "Vos notifications n’ont pas pu être chargées ; actualisez la page.",
    "De mails gaan naar het adres waarmee je inlogt.": "Les e-mails sont envoyés à l’adresse avec laquelle vous vous connectez.",
    "Zet je een soort uit, dan stuurt CUSTOM+ die mails niet meer; in het portaal zie je alles nog gewoon.": "Si vous désactivez un type, CUSTOM+ n’envoie plus ces e-mails ; dans le portail, vous voyez toujours tout.",
    "Welke mail je collega’s krijgen, regel je per persoon onder Jouw mensen.": "Les e-mails que reçoivent vos collègues se règlent par personne sous Vos collaborateurs.",
    "Je keuze geldt meteen voor dit portaal; je mails komen in het Nederlands of anders in het Engels.": "Votre choix s’applique immédiatement à ce portail ; vos e-mails arrivent en néerlandais ou sinon en anglais.",
    "De keuze wordt bewaard als jouw voorkeur bij CUSTOM+.": "Ce choix est enregistré comme votre préférence chez CUSTOM+.",
    "De mails van CUSTOM+ bestaan alleen in het Nederlands en het Engels; kies je een andere taal, dan komen je mails in het Engels.": "Les e-mails de CUSTOM+ n’existent qu’en néerlandais et en anglais ; si vous choisissez une autre langue, vos e-mails arrivent en anglais.",
    "Het portaal legt geen inlogmoment vast; wat het wél vastlegt is een bestand bekijken of downloaden, een akkoord geven, een betaling melden.": "Le portail n’enregistre pas le moment de connexion ; ce qu’il enregistre, c’est la consultation ou le téléchargement d’un fichier, une validation, un paiement signalé.",
    "De apparaten waarmee je zelf iets deed in {product}; een aparte inlogregel is er niet.": "Les appareils avec lesquels vous avez agi dans {product} ; il n’y a pas de ligne de connexion distincte.",
    "De apparaten waarmee je zelf iets deed in je product; een aparte inlogregel is er niet.": "Les appareils avec lesquels vous avez agi dans votre produit ; il n’y a pas de ligne de connexion distincte.",
    "Alles wat dit portaal over jou bewaart als één JSON-bestand, zonder de foto’s en PDF’s zelf.": "Tout ce que ce portail conserve sur vous en un seul fichier JSON, sans les photos et les PDF eux-mêmes.",
    "Erin: producten en fases, foto’s en documenten, facturen, samples, berichten, zendingen, je mensen en je herbestellingen; zonder interne notities van CUSTOM+.": "Contenu : produits et phases, photos et documents, factures, samples, messages, expéditions, vos collaborateurs et vos réassorts ; sans les notes internes de CUSTOM+.",
    "De bestanden zelf download je per stuk onder Bestanden.": "Les fichiers eux-mêmes se téléchargent un par un sous Fichiers.",
    "Wat er wordt vastgelegd: wanneer je een bestand bekijkt of downloadt, en elke handeling die je in dit portaal doet — een akkoord, een samplekeuze, een gemelde betaling, een bericht, een upload; dat logboek lees je zelf onder Activiteit.": "Ce qui est enregistré : quand vous consultez ou téléchargez un fichier, et chaque action que vous faites dans ce portail — une validation, un choix de sample, un paiement signalé, un message, un envoi de fichier ; vous pouvez lire ce journal vous-même sous Activité.",
    "Wil je iets laten aanpassen of verwijderen, stuur Steffan dan een bericht.": "Si vous souhaitez faire modifier ou supprimer quelque chose, envoyez un message à Steffan.",
