    "Je idee wordt uitgewerkt tot een ontwerp dat echt te maken is; dit duurt meestal 1 tot 2 weken.": "Votre idée est développée en une conception réellement fabricable ; cela prend généralement 1 à 2 semaines.",
    "Het ontwerp wordt doorgerekend voor de fabriek, zodat het zonder verrassingen te produceren is; dit duurt meestal 2 tot 4 weken.": "La conception est passée au crible pour l’usine, afin qu’elle puisse être produite sans surprise ; cela prend généralement 2 à 4 semaines.",
