    "Contracten, offertes, facturen en rapporten, geordend per fase. Elke download wordt in het logboek genoteerd.": "Contratos, presupuestos, facturas e informes, ordenados por fase. Cada descarga queda anotada en el registro.",
    "Demo-omgeving": "Entorno de demostración",
