    "Bestand niet beschikbaar in deze browser": "Archivo no disponible en este navegador",
    "Dit bestand staat in de browseropslag van de computer waarop het is geüpload en reist niet mee naar andere browsers. Open het portaal daar, of mail steffan@customplus.nl.": "Este archivo está guardado en el navegador del ordenador donde se subió y no viaja a otros navegadores. Abra el portal allí o escriba a steffan@customplus.nl.",
    "Deze download is wel in je toegangslogboek genoteerd, zodat je ziet hoe dat werkt.": "Esta descarga sí quedó anotada en su registro de accesos, para que vea cómo funciona.",
    "Het bestand kon nu niet worden opgehaald. Probeer het over een minuut opnieuw of mail steffan@customplus.nl.": "No se pudo obtener el archivo. Inténtelo de nuevo en un minuto o escriba a steffan@customplus.nl.",
