    "Scan de code met je bank-app: bedrag en kenmerk staan er al in. Liever handmatig? Neem dan bovenstaande gegevens over en vermeld het kenmerk.": "Escanee el código con su aplicación bancaria: el importe y la referencia ya están incluidos. ¿Prefiere hacerlo manualmente? Copie los datos anteriores e indique la referencia.",
