    "Steffan beantwoordde je vraag: ‘{x}’": "Steffan respondió a su pregunta: ‘{x}’",
    "Nieuw document: {x}": "Nuevo documento: {x}",
    "FACTUUR": "FACTURA",
    "Factuur betaald: {x}": "Factura pagada: {x}",
    "Er staat een factuur voor je klaar: {x}": "Hay una factura lista para usted: {x}",
    "Zending: {x}": "Envío: {x}",
    "goedgekeurd": "aprobada",
    "Uitleg: {term}": "Explicación: {term}",
    "Lees meer op de site": "Leer más en el sitio",
    "De statistische norm die bepaalt hoeveel afwijkingen een steekproef mag bevatten voordat de hele batch wordt afgekeurd. Elke inspectie in je portaal wordt tegen deze norm gemeten.": "La norma estadística que determina cuántas desviaciones puede contener un muestreo antes de rechazar todo el lote. Cada inspección de su portal se mide contra esta norma.",
    "Een contract dat is opgesteld om afdwingbaar te zijn bij Chinese rechtbanken, getekend vóór er één bestand de deur uit gaat. Een westerse NDA alleen is dat in de praktijk vaak niet.": "Un contrato redactado para ser exigible ante los tribunales chinos, firmado antes de que salga un solo archivo. Un NDA occidental por sí solo a menudo no lo es en la práctica.",
    "De stap waarin je ontwerp wordt getoetst aan het productieproces dat het echt gaat maken, vóór er tooling wordt besteld. Een mooi CAD bestand en een maakbaar onderdeel zijn niet hetzelfde.": "El paso en el que su diseño se contrasta con el proceso de producción que realmente lo fabricará, antes de encargar el utillaje. Un bonito archivo CAD y una pieza fabricable no son lo mismo.",
    "De kleinste oplage die een fabriek wil draaien. Voor spuitgietwerk ligt die doorgaans hoger dan voor CNC of plaatwerk, omdat de mal moet worden terugverdiend.": "La tirada más pequeña que una fábrica está dispuesta a producir. En inyección suele ser mayor que en CNC o chapa, porque el molde debe amortizarse.",
    "De controle van binnenkomend materiaal vóórdat de productie start, zodat een afwijking in de grondstof nooit een hele run kan raken.": "El control del material entrante antes de que arranque la producción, para que una desviación en la materia prima nunca pueda afectar a toda una tirada.",
    "Controles tijdens de productierun zelf, niet pas aan het einde — zo wordt een afwijking gevonden terwijl die nog goedkoop te herstellen is.": "Controles durante la propia producción, no solo al final — así una desviación se detecta cuando aún es barata de corregir.",
    "De eindcontrole op de afgeronde batch, vlak vóór verzending, gemeten tegen hetzelfde golden sample waarmee de run begon.": "El control final del lote terminado, justo antes del envío, medido contra el mismo golden sample con el que empezó la tirada.",
    "Het allereerste schot uit een nieuwe mal. Een T0 is zelden meteen goed — deze ronde laat zien wat er aan de mal moet worden bijgesteld.": "El primer disparo de un molde nuevo. Un T0 rara vez sale bien a la primera — esta ronda muestra qué hay que ajustar en el molde.",
    "De sampleronde na de eerste bijstelling van de mal. Elke volgende ronde brengt het sample dichter bij het exemplaar dat jij goedkeurt.": "La ronda de muestras tras el primer ajuste del molde. Cada ronda siguiente acerca la muestra al ejemplar que usted aprueba.",
    "De ronde na de tweede bijstelling, vaak de laatste verfijning zoals polijstwerk aan de mal. Keur jij deze goed, dan wordt dit exemplaar meestal het golden sample.": "La ronda tras el segundo ajuste, a menudo el último refinado, como el pulido del molde. Si usted la aprueba, este ejemplar suele convertirse en el golden sample.",
    "Het sample dat jij goedkeurt als dé standaard. Elke inspectie tijdens de productie meet de batch tegen precies dit exemplaar — niet tegen een gevoel.": "La muestra que usted aprueba como el estándar. Cada inspección durante la producción mide el lote contra exactamente este ejemplar — no contra una sensación.",
    "Het officiële vervoersdocument van een zeevracht: het bewijs dat de lading aan boord is én het document waarmee de container op de bestemming wordt vrijgegeven.": "El documento de transporte oficial de un flete marítimo: la prueba de que la carga está a bordo y el documento con el que se libera el contenedor en destino.",
    /* factuurmodule fase 5 — de herinneringsteksten */
    "Herinnering: factuur {nummer} vervalt {vervaldatum}": "Recordatorio: la factura {nummer} vence el {vervaldatum}",
    "Beste {naam},\n\nEen vriendelijke herinnering: factuur {nummer} van {bedrag} vervalt op {vervaldatum}.\n\nIs de betaling al onderweg, dan kun je dit bericht als niet verzonden beschouwen.\n\nMet vriendelijke groet,\n{afzender}": "Estimado/a {naam}:\n\nUn recordatorio amable: la factura {nummer} por {bedrag} vence el {vervaldatum}.\n\nSi el pago ya está en camino, haga caso omiso de este mensaje.\n\nUn cordial saludo,\n{afzender}",
    "Factuur {nummer} staat nog open": "La factura {nummer} sigue pendiente",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} is op {vervaldatum} vervallen en staat nog open. Waarschijnlijk is het je ontgaan.\n\nHet openstaande bedrag is {openstaand}. Klopt er iets niet, laat het dan weten — dan lossen we het samen op.\n\nMet vriendelijke groet,\n{afzender}": "Estimado/a {naam}:\n\nLa factura {nummer} por {bedrag} venció el {vervaldatum} y sigue pendiente. Probablemente se le haya pasado.\n\nEl importe pendiente es de {openstaand}. Si algo no cuadra, díganoslo y lo resolvemos juntos.\n\nUn cordial saludo,\n{afzender}",
    "Tweede herinnering: factuur {nummer}": "Segundo recordatorio: factura {nummer}",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} staat sinds {vervaldatum} open. Het openstaande bedrag is {openstaand}.\n\nWe hebben nog geen betaling ontvangen en ook geen bericht. Wil je de betaling deze week in orde maken, of laten weten waar het aan ligt?\n\nMet vriendelijke groet,\n{afzender}": "Estimado/a {naam}:\n\nLa factura {nummer} por {bedrag} está pendiente desde el {vervaldatum}. El importe pendiente es de {openstaand}.\n\nNo hemos recibido ni el pago ni ningún mensaje. ¿Podría realizar el pago esta semana o indicarnos qué lo está retrasando?\n\nUn cordial saludo,\n{afzender}",
    "Laatste aanmaning: factuur {nummer}": "Último aviso: factura {nummer}",
    "Beste {naam},\n\nOndanks eerdere herinneringen staat factuur {nummer} nog open. Het openstaande bedrag is {openstaand}, vervallen op {vervaldatum}.\n\nDit is de laatste aanmaning. Zonder betaling of bericht binnen veertien dagen dragen we de vordering over.\n\nMet vriendelijke groet,\n{afzender}": "Estimado/a {naam}:\n\nA pesar de recordatorios anteriores, la factura {nummer} sigue pendiente. El importe pendiente es de {openstaand}, vencido el {vervaldatum}.\n\nEste es el último aviso. Sin pago ni respuesta en catorce días, cederemos el cobro.\n\nUn cordial saludo,\n{afzender}",
    "Over factuur {nummer}": "Sobre la factura {nummer}",
    "Beste {naam},\n\nFactuur {nummer} van {bedrag} staat nog open; het openstaande bedrag is {openstaand}.\n\nMet vriendelijke groet,\n{afzender}": "Estimado/a {naam}:\n\nLa factura {nummer} por {bedrag} sigue pendiente; el importe pendiente es de {openstaand}.\n\nUn cordial saludo,\n{afzender}",
    "Rente over de te late betaling": "Intereses por demora en el pago",
    "Buitengerechtelijke incassokosten": "Gastos de cobro extrajudiciales",
