    "Vraag of betaalprobleem melden": "Comunicar una pregunta o un problema de pago",
    "Stel je vraag, of laat weten waar de betaling vastloopt. Je bericht komt binnen bij Steffan zelf, op dezelfde plek als je andere projectvragen. Je hoort meestal binnen 1 werkdag iets.": "Haga su pregunta o díganos dónde se atasca el pago. Su mensaje llega al propio Steffan, en el mismo sitio que sus demás preguntas del proyecto. Suele recibir respuesta en 1 día laborable.",
