    "Bedankt — je bericht is binnengekomen. Je hoort meestal binnen 1 werkdag iets.": "Gracias — su mensaje ha llegado. Suele recibir respuesta en 1 día laborable.",
    "Je bericht kon niet worden verstuurd. Probeer het zo nog eens, of mail steffan@customplus.nl.": "No se ha podido enviar su mensaje. Inténtelo de nuevo en un momento o escriba a steffan@customplus.nl.",
    "Deze pagina hoort bij één factuur en is alleen voor jou bedoeld. Deel de link niet — wie hem heeft, kan deze factuur bekijken.": "Esta página corresponde a una sola factura y es solo para usted. No comparta el enlace — quien lo tenga podrá ver esta factura.",
    /* klantportaal 2026-09 — hoofdstuk: schermen, acties, foutzinnen */
