    "Activiteit": "Actividad",
    "Al overgemaakt? Meld het hier. Een melding is geen boeking: Steffan controleert je betaling en zet de factuur daarna op betaald.": "¿Ya ha hecho la transferencia? Comuníquelo aquí. Una comunicación no es un asiento: Steffan comprueba su pago y después marca la factura como pagada.",
    "Alle {n} foto’s": "Las {n} fotos",
    "Alles is betaald.": "Todo está pagado.",
    "Alles wat dit portaal over jou en je producten bewaart, als één JSON-bestand: producten en fases, foto’s en documenten, facturen, samples, berichten, zendingen, je mensen en je herbestellingen. Zonder interne notities van CUSTOM+.": "Todo lo que este portal guarda sobre usted y sus productos, en un solo archivo JSON: productos y fases, fotos y documentos, facturas, samples, mensajes, envíos, su equipo y sus pedidos repetidos. Sin notas internas de CUSTOM+.",
    "Alles wat jou aangaat in dit product: updates van Steffan, je eigen handelingen, foto’s, berichten, betalingen en zendingen. Interne notities van CUSTOM+ staan hier niet.": "Todo lo que le concierne en este producto: actualizaciones de Steffan, sus propias acciones, fotos, mensajes, pagos y envíos. Las notas internas de CUSTOM+ no aparecen aquí.",
