    "Dit onderdeel wordt nog gebouwd.": "Esta sección aún se está construyendo.",
    "Dit onderdeel wordt nog gebouwd. Je taal kies je in het gebruikersmenu rechtsboven; daar staat ook Download alles.": "Esta sección aún se está construyendo. Su idioma lo elige en el menú de usuario, arriba a la derecha; ahí está también Descargar todo.",
    "Dit overzicht hoort bij het product dat nu open staat; wissel van product om een ander logboek te zien.": "Este resumen corresponde al producto abierto ahora; cambie de producto para ver otro registro.",
    "Dit product kon niet worden gevonden.": "No se ha encontrado este producto.",
    "Dit zijn jouw eigen mails. Welke mail je collega’s krijgen, regel je per persoon onder Jouw mensen.": "Estos son sus propios correos. Qué correos reciben sus compañeros lo configura por persona en Su equipo.",
    "Download alles": "Descargar todo",
    "Download alles geeft je een bestand met alles wat je in het portaal ziet: producten, documenten, facturen en gesprekken, zonder interne velden.": "Descargar todo le da un archivo con todo lo que ve en el portal: productos, documentos, facturas y conversaciones, sin campos internos.",
    "Downloaden is hier nog niet beschikbaar.": "La descarga aún no está disponible aquí.",
    "Een creditnota vermindert wat je nog moet betalen. Het bedrag is al verrekend in de stand van de bijbehorende factuur.": "Una nota de abono reduce lo que aún tiene que pagar. El importe ya está descontado en el saldo de la factura correspondiente.",
    "Elk bestandstype kan, tot {mb} MB — bijvoorbeeld PDF, JPG, PNG, AI of ZIP.": "Vale cualquier tipo de archivo, hasta {mb} MB — por ejemplo PDF, JPG, PNG, AI o ZIP.",
    "Elke factuur die Steffan publiceert, staat hier met haar stand, vervaldatum en betaalgegevens.": "Cada factura que publica Steffan aparece aquí con su estado, su fecha de vencimiento y sus datos de pago.",
    "Er is wel activiteit van andere soorten. Kies “Alles” om de volledige tijdlijn te zien.": "Sí hay actividad de otros tipos. Elija «Todo» para ver la cronología completa.",
    "Er staat niets open.": "No hay nada pendiente.",
    "Er staat nog geen product open": "Todavía no hay ningún producto abierto",
