    "Het adres wijst naar iets wat het portaal niet kent.": "La dirección apunta a algo que el portal no conoce.",
    "Het factuurnummer, of de omschrijving die je bij je bank hebt gebruikt.": "El número de factura, o el concepto que ha usado en su banco.",
    "Het hoort niet bij jouw account, of het bestaat niet meer.": "No pertenece a su cuenta, o ya no existe.",
    "Het portaal legt geen aparte inlogregel vast. Dit zijn de apparaten waarmee je iets deed in je product: een bestand bekeken of gedownload, een akkoord gegeven, een betaling gemeld.": "El portal no registra un inicio de sesión aparte. Estos son los dispositivos con los que hizo algo en su producto: ver o descargar un archivo, dar una aprobación, comunicar un pago.",
    "Hoofdcontactpersoon — logt in en ontvangt de mails die je onder Meldingen aanzet.": "Contacto principal — inicia sesión y recibe los correos que active en Notificaciones.",
    "In de voorvertoning wisselt alleen dit scherm van taal; de voorkeur van de klant blijft staan.": "En la vista previa solo cambia de idioma esta pantalla; la preferencia del cliente se mantiene.",
    "In {valuta}, bijvoorbeeld 1234,56": "En {valuta}, por ejemplo 1234,56",
    "Ingelogd als hoofdcontactpersoon van dit account.": "Sesión iniciada como contacto principal de esta cuenta.",
    "Instellingen": "Ajustes",
    "Ja, verwijderen": "Sí, eliminar",
    "Je bent de hoofdcontactpersoon van dit account. De mails van CUSTOM+ komen op dit adres; wat je precies krijgt, stel je in onder Meldingen.": "Usted es el contacto principal de esta cuenta. Los correos de CUSTOM+ llegan a esta dirección; qué recibe exactamente lo configura en Notificaciones.",
    "Je bericht komt in de Inbox van Steffan. Hij reageert meestal binnen 1 werkdag.": "Su mensaje llega a la bandeja de entrada de Steffan. Suele responder en 1 día laborable.",
    "Je betaling is gemeld.": "Su pago ha sido comunicado.",
    "Je dossier wordt gedownload als JSON-bestand.": "Su expediente se descarga como archivo JSON.",
    "Je dossier wordt samengesteld…": "Se está preparando su expediente…",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase. Alleen jij, via je login, en CUSTOM+ kunnen erbij.": "Sus datos están en la base de datos de CUSTOM+ en Supabase. Solo usted, mediante su acceso, y CUSTOM+ pueden consultarlos.",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase. Elke rij is met toegangsregels beperkt tot je eigen klantaccount: alleen jij, via je login, en CUSTOM+ kunnen erbij.": "Sus datos están en la base de datos de CUSTOM+ en Supabase. Cada fila está limitada por reglas de acceso a su propia cuenta de cliente: solo usted, mediante su acceso, y CUSTOM+ pueden consultarlos.",
    "Je hebt een vraag over deze factuur gesteld. Steffan neemt contact met je op; tot die tijd staan de herinneringen stil en hoef je niets te doen.": "Ha planteado una pregunta sobre esta factura. Steffan se pondrá en contacto con usted; hasta entonces los recordatorios están en pausa y no tiene que hacer nada.",
    "Je huidige voorkeuren konden niet worden geladen; hieronder staat de standaard.": "No se han podido cargar sus preferencias actuales; abajo se muestra la configuración predeterminada.",
    "Je keuze geldt meteen voor dit portaal en wordt bewaard als jouw voorkeur bij CUSTOM+.": "Su elección se aplica de inmediato a este portal y se guarda como su preferencia en CUSTOM+.",
    "Je kijkt mee als beheerder. In de voorvertoning kun je hier niets wijzigen; wat je aanpast wordt niet bewaard.": "Está viendo como administrador. En la vista previa no puede cambiar nada aquí; lo que ajuste no se guarda.",
    "Je kijkt naar de tijdlijn van het product dat nu open staat. Een ander product kies je via Producten.": "Está viendo la cronología del producto abierto ahora. Otro producto lo elige en Productos.",
    "Je laatste handelingen": "Sus últimas acciones",
    "Je meldingen konden niet worden geladen.": "No se han podido cargar sus notificaciones.",
    "Je vraag is verstuurd.": "Su pregunta se ha enviado.",
    "Je vraag komt in de Inbox van Steffan. Hij leest en beantwoordt elk bericht zelf, meestal binnen 1 werkdag.": "Su pregunta llega a la bandeja de entrada de Steffan. Lee y responde personalmente cada mensaje, normalmente en 1 día laborable.",
    "Je werkt in de demo. Alles wat je hier doet staat alleen in deze browser en verdwijnt zodra je de browsergegevens wist.": "Está trabajando en la demo. Todo lo que haga aquí está solo en este navegador y desaparece en cuanto borre los datos del navegador.",
    "Je werkt in de demo. Alles wat je hier doet staat alleen in deze browser, in de browseropslag die het portaal en het beheer op dit apparaat delen. Het verdwijnt zodra je de browsergegevens wist en bereikt geen server.": "Está trabajando en la demo. Todo lo que haga aquí está solo en este navegador, en el almacenamiento que el portal y la administración comparten en este dispositivo. Desaparece en cuanto borre los datos del navegador y no llega a ningún servidor.",
