    "Van deze regel is alleen de dag vastgelegd, niet het tijdstip.": "De esta línea solo se registró el día, no la hora.",
    "Van je mensen bewaart CUSTOM+ alleen wat jij invult: naam, functie, e-mailadres en de gekozen soorten mail.": "De su equipo, CUSTOM+ guarda solo lo que usted introduce: nombre, cargo, correo electrónico y los tipos de correo elegidos.",
