    "Vervallen op {datum}": "Vencida el {datum}",
    "Vervalt op {datum}": "Vence el {datum}",
    "Verwacht in de fase {fase}.": "Previsto en la fase {fase}.",
    "Verwijderen": "Eliminar",
    "Vier onderdelen: je mensen, je meldingen, je taal en je gegevens. Bij je mensen en je meldingen staan wijzigingen pas vast als je ze opslaat; je krijgt een waarschuwing als je met onopgeslagen werk wegloopt.": "Cuatro secciones: su equipo, sus notificaciones, su idioma y sus datos. En su equipo y sus notificaciones, los cambios solo quedan fijados cuando los guarda; recibirá un aviso si se va con trabajo sin guardar.",
    "Voeg iemand toe die mee wil lezen — een collega van inkoop, marketing of ontwerp — en kies welke mail hij of zij krijgt.": "Añada a alguien que quiera seguir el proyecto — un compañero de compras, marketing o diseño — y elija qué correos recibe.",
    "Volgende betaling": "Próximo pago",
    "Vraag over deze factuur": "Pregunta sobre esta factura",
    "Vraagt Steffan om een logo, artwork of specificatie, dan staat het hier met een uploadknop.": "Si Steffan pide un logotipo, un artwork o una especificación, aparece aquí con un botón para subirlo.",
    "Vragen over je gegevens?": "¿Preguntas sobre sus datos?",
    "Vul de datum van je betaling in.": "Introduzca la fecha de su pago.",
    "Vul een bedrag in dat groter is dan nul.": "Introduzca un importe mayor que cero.",
    "Vul een naam in.": "Introduzca un nombre.",
    "Waar je gegevens staan": "Dónde están sus datos",
    "Waar je gegevens staan, hangt af van de omgeving waarin dit portaal draait; die kon nu niet worden vastgesteld.": "Dónde están sus datos depende del entorno en el que funciona este portal; ahora mismo no se ha podido determinar.",
    "Waar je gegevens staan, lees je onder Toegang en gegevens.": "Dónde están sus datos lo puede leer en Acceso y datos.",
    "Wacht op jou": "Le espera",
    "Wat er van je wordt bewaard, en waar": "Qué se guarda sobre usted, y dónde",
    "Wat er wordt vastgelegd: wanneer je een bestand bekijkt of downloadt, en elke handeling die je in dit portaal doet — een akkoord, een samplekeuze, een gemelde betaling, een bericht, een upload. Dat logboek lees je zelf onder Activiteit.": "Qué se registra: cuándo ve o descarga un archivo, y cada acción que realiza en este portal — una aprobación, una decisión sobre un sample, un pago comunicado, un mensaje, una subida. Ese registro lo lee usted mismo en Actividad.",
    "Wat je keuze doet": "Qué hace su elección",
    "Wat je mensen krijgen": "Qué recibe su equipo",
    "Wat klopt er niet?": "¿Qué no cuadra?",
    "Wat we van jou nodig hebben": "Qué necesitamos de usted",
