    "Wil je iets laten aanpassen of verwijderen? Stuur Steffan een bericht; hij regelt het zelf.": "¿Quiere que se modifique o elimine algo? Envíe un mensaje a Steffan; él se encarga personalmente.",
    "Zet je een soort uit, dan stuurt CUSTOM+ die mails niet meer naar dit adres. In het portaal zie je alles nog gewoon.": "Si desactiva un tipo, CUSTOM+ deja de enviar esos correos a esta dirección. En el portal seguirá viendo todo con normalidad.",
    "Zodra Steffan bestanden onder NNN met een fabriek deelt, staat hier welk bestand, welke fabriek en wanneer.": "En cuanto Steffan comparta archivos bajo NNN con una fábrica, aquí verá qué archivo, qué fábrica y cuándo.",
    "Zodra er iets gebeurt — een update, een foto, een bericht, een betaling — verschijnt het hier.": "En cuanto ocurra algo — una actualización, una foto, un mensaje, un pago — aparecerá aquí.",
    "Zodra je hier een bestand opent of iets bevestigt, verschijnt het apparaat waarmee je dat deed.": "En cuanto abra aquí un archivo o confirme algo, aparecerá el dispositivo con el que lo hizo.",
    "Zonder NNN": "Sin NNN",
    "Zonder e-mailadres kan deze persoon geen mail krijgen. Vul een adres in of zet de soorten mail uit.": "Sin correo electrónico, esta persona no puede recibir correos. Introduzca una dirección o desactive los tipos de correo.",
