    "Alles wat jou aangaat in dit product: updates, foto’s, berichten, betalingen en zendingen.": "Todo lo que le concierne en este producto: actualizaciones, fotos, mensajes, pagos y envíos.",
    "Ook je eigen handelingen staan erin: een akkoord, een samplekeuze, een gemelde betaling, een download.": "También aparecen sus propias acciones: una aprobación, una decisión sobre un sample, un pago comunicado, una descarga.",
    "Interne notities van CUSTOM+ staan hier niet.": "Las notas internas de CUSTOM+ no aparecen aquí.",
    "Je kijkt naar de tijdlijn van het product dat nu open staat.": "Está viendo la cronología del producto que está abierto ahora.",
    "De mails van CUSTOM+ komen op dit adres.": "Los correos de CUSTOM+ llegan a esta dirección.",
    "Je bent de hoofdcontactpersoon van dit account; wat je precies krijgt, stel je in onder Meldingen.": "Usted es el contacto principal de esta cuenta; qué recibe exactamente lo configura en Notificaciones.",
    "Je gegevens staan in de database van CUSTOM+ bij Supabase; alleen jij en CUSTOM+ kunnen erbij.": "Sus datos están en la base de datos de CUSTOM+ en Supabase; solo usted y CUSTOM+ pueden consultarlos.",
    "Elke rij is met toegangsregels beperkt tot je eigen klantaccount, via je login.": "Cada fila está limitada por reglas de acceso a su propia cuenta de cliente, mediante su acceso.",
    "Je werkt in de demo: alles staat alleen in deze browser en bereikt geen server.": "Está trabajando en la demo: todo está solo en este navegador y no llega a ningún servidor.",
    "Het portaal en het beheer delen op dit apparaat dezelfde browseropslag; alles verdwijnt zodra je de browsergegevens wist.": "El portal y la administración comparten el mismo almacenamiento del navegador en este dispositivo; todo desaparece en cuanto borre los datos del navegador.",
    "Je mensen, je meldingen, je taal en je gegevens.": "Su equipo, sus notificaciones, su idioma y sus datos.",
    "Bij je mensen en je meldingen staan wijzigingen pas vast als je ze opslaat; loop je weg met onopgeslagen werk, dan krijg je een waarschuwing.": "En su equipo y sus notificaciones, los cambios solo quedan fijados cuando los guarda; si se va con trabajo sin guardar, recibirá un aviso.",
    "Je kijkt mee als beheerder: in de voorvertoning wordt niets bewaard.": "Está viendo como administrador: en la vista previa no se guarda nada.",
    "Dit vinkje is een aanvraag: Steffan maakt de toegang aan en nodigt deze persoon per mail uit.": "Esta casilla es una solicitud: Steffan crea el acceso e invita a esta persona por correo.",
    "De lijst met je mensen kon niet worden geladen; vernieuw de pagina.": "No se ha podido cargar la lista de su equipo; actualice la página.",
    "Per persoon kies je welke soorten mail iemand krijgt; jouw eigen mails regel je onder Meldingen.": "Por persona elige qué tipos de correo recibe; sus propios correos los configura en Notificaciones.",
    "Iemand zonder soorten krijgt geen mail; iedereen met een login ziet alles in dit portaal.": "Quien no tenga ningún tipo no recibe correo; todos los que tienen acceso ven todo en este portal.",
    "Je meldingen konden niet worden geladen; vernieuw de pagina.": "No se han podido cargar sus notificaciones; actualice la página.",
    "De mails gaan naar het adres waarmee je inlogt.": "Los correos se envían a la dirección con la que inicia sesión.",
    "Zet je een soort uit, dan stuurt CUSTOM+ die mails niet meer; in het portaal zie je alles nog gewoon.": "Si desactiva un tipo, CUSTOM+ deja de enviar esos correos; en el portal sigue viendo todo.",
    "Welke mail je collega’s krijgen, regel je per persoon onder Jouw mensen.": "Qué correos reciben sus compañeros lo configura por persona en Su equipo.",
    "Je keuze geldt meteen voor dit portaal; je mails komen in het Nederlands of anders in het Engels.": "Su elección se aplica de inmediato a este portal; sus correos llegan en neerlandés o, si no, en inglés.",
    "De keuze wordt bewaard als jouw voorkeur bij CUSTOM+.": "La elección se guarda como su preferencia en CUSTOM+.",
    "De mails van CUSTOM+ bestaan alleen in het Nederlands en het Engels; kies je een andere taal, dan komen je mails in het Engels.": "Los correos de CUSTOM+ solo existen en neerlandés y en inglés; si elige otro idioma, sus correos llegan en inglés.",
    "Het portaal legt geen inlogmoment vast; wat het wél vastlegt is een bestand bekijken of downloaden, een akkoord geven, een betaling melden.": "El portal no registra el momento de inicio de sesión; lo que sí registra es ver o descargar un archivo, dar una aprobación, comunicar un pago.",
    "De apparaten waarmee je zelf iets deed in {product}; een aparte inlogregel is er niet.": "Los dispositivos con los que hizo algo en {product}; no hay un registro de inicio de sesión aparte.",
    "De apparaten waarmee je zelf iets deed in je product; een aparte inlogregel is er niet.": "Los dispositivos con los que hizo algo en su producto; no hay un registro de inicio de sesión aparte.",
    "Alles wat dit portaal over jou bewaart als één JSON-bestand, zonder de foto’s en PDF’s zelf.": "Todo lo que este portal guarda sobre usted en un solo archivo JSON, sin las fotos ni los PDF en sí.",
    "Erin: producten en fases, foto’s en documenten, facturen, samples, berichten, zendingen, je mensen en je herbestellingen; zonder interne notities van CUSTOM+.": "Incluye: productos y fases, fotos y documentos, facturas, samples, mensajes, envíos, su equipo y sus pedidos repetidos; sin notas internas de CUSTOM+.",
    "De bestanden zelf download je per stuk onder Bestanden.": "Los archivos en sí los descarga uno a uno en Archivos.",
    "Wat er wordt vastgelegd: wanneer je een bestand bekijkt of downloadt, en elke handeling die je in dit portaal doet — een akkoord, een samplekeuze, een gemelde betaling, een bericht, een upload; dat logboek lees je zelf onder Activiteit.": "Lo que se registra: cuándo ve o descarga un archivo, y cada acción que realiza en este portal — una aprobación, una decisión sobre un sample, un pago comunicado, un mensaje, una subida; ese registro lo puede leer usted mismo en Actividad.",
    "Wil je iets laten aanpassen of verwijderen, stuur Steffan dan een bericht.": "Si quiere que se modifique o elimine algo, envíe un mensaje a Steffan.",
